	public static AttackInfo GetInfoFromData(Entity givenEnt, StatData givenData, int givenLevel, bool givenUlt)
	{
		if (givenData == null)
		{
			return null;
		}
		generatedAtkInfo = new AttackInfo();
		generatedAtkInfo.entity = givenEnt;
		generatedAtkInfo.gameObject = ((!(givenEnt != null)) ? null : givenEnt.gameObject);
		generatedAtkInfo.skillID = givenData.GetValue<string>("ID", givenLevel);
		generatedAtkInfo.skillCategory = givenData.category;
		generatedAtkInfo.skillLevel = givenLevel;
		generatedAtkInfo.isUltimate = givenUlt;
		generatedAtkInfo.attackInfoKey = generatedAtkInfo.skillCategory + generatedAtkInfo.skillID + generatedAtkInfo.skillLevel;
		generatedAtkInfo.elementType = Globals.StrToElement(givenData.GetValue<string>(StatData.eleStr, givenLevel));
		generatedAtkInfo.subElementType = Globals.StrToElement(givenData.GetValue<string>(StatData.subEleStr, givenLevel));
		generatedAtkInfo.showDamageNumber = givenData.GetValue<bool>(StatData.showNumStr, givenLevel);
		generatedAtkInfo.showDamageEffect = givenData.GetValue<bool>(StatData.showEffStr, givenLevel);
		generatedAtkInfo.shakeCamera = givenData.GetValue<bool>(StatData.shakeCamStr, givenLevel);
		generatedAtkInfo.targetNames = new List<string>(givenData.GetValue<List<string>>(StatData.targetStr, givenLevel));
		generatedAtkInfo.sameTargetImmunityTime = givenData.GetValue<float>(StatData.sameTrgStr, givenLevel);
		generatedAtkInfo.sameAttackImmunityTime = givenData.GetValue<float>(StatData.sameAtkStr, givenLevel);
		generatedAtkInfo.canHitStun = givenData.GetValue<bool>(StatData.canStunStr, givenLevel);
		generatedAtkInfo.hitStunDurationModifier = givenData.GetValue<float>(StatData.stunDurStr, givenLevel);
		generatedAtkInfo.knockbackMultiplier = givenData.GetValue<float>(StatData.kbMultiStr, givenLevel);
		generatedAtkInfo.knockbackOverwrite = givenData.GetValue<bool>(StatData.kbOverStr, givenLevel);
		generatedAtkInfo.damage = givenData.GetValue<int>(StatData.damageStr, givenLevel);
		generatedAtkInfo.critHitChance = givenData.GetValue<float>(StatData.critChStr, givenLevel);
		generatedAtkInfo.critDmgModifier = givenData.GetValue<float>(StatData.critDmgStr, givenLevel);
		if (givenData.HasOverrideMod(StatData.damageStr))
		{
			generatedAtkInfo.isDamageOverride = true;
		}
		generatedAtkInfo.isStatusEffect = givenData.GetValue<bool>(StatData.isStatStr, givenLevel);
		generatedAtkInfo.chaosChance = givenData.GetValue<float>(StatData.chaosChStr, givenLevel);
		generatedAtkInfo.chaosLevel = givenData.GetValue<int>(StatData.chaosLvStr, givenLevel);
		generatedAtkInfo.burnChance = givenData.GetValue<float>(StatData.burnChStr, givenLevel);
		generatedAtkInfo.burnLevel = givenData.GetValue<int>(StatData.burnLvStr, givenLevel);
		generatedAtkInfo.slowChance = givenData.GetValue<float>(StatData.slowChStr, givenLevel);
		generatedAtkInfo.slowLevel = givenData.GetValue<int>(StatData.slowLvStr, givenLevel);
