	private Vector2 currentPosition;

	private StatData ultSkillData;

	private string calcSkillID;

	public override string OnEnterAnimStr => parent.GSlamAnimStr;

	public UsePhantomKnights(FSM fsm, Player parentPlayer)
		: base(staticID, fsm, parentPlayer)
	{
		hasSignatureVariant = true;
		empoweredStat.SetInitialBaseValue(newBaseVal: true);
		SetAnimTimes(0.15f);
		ultSkillData = StatManager.GetSkillData(parent.skillCategory, ultSkillID);
	}

	public override void SetEmpowered(bool gs, BoolVarStatMod gm)
	{
	}

	public override void ExecuteSkill()
	{
		base.ExecuteSkill();
		currentPosition = parent.transform.position;
		if (isUltimate)
		{
			calcSkillID = ultSkillID;
			SyncUltSkillData();
			skillLevelList.Shuffle();
		}
		else
		{
			calcSkillID = skillID;
		}
		for (int i = 0; i < 5; i++)
		{
			spawnPosition = Globals.GetLinecastVector(currentPosition, currentPosition + Globals.GetCirclePositionVector(5, i) * 2.5f, ChaosCollisions.layerAllWallAndObst);
			currentPK = Globals.ChaosInst<PhantomKnight>(PhantomKnight.Prefab, parent.playerObjTrans, spawnPosition);
			currentPK.parentObj = parent.gameObject;
			currentPK.skillCategory = parent.skillCategory;
			currentPK.skillID = calcSkillID;
			currentPK.chargeAnimThreshold = 0.75f + (float)i * 0.15f;
			currentPK.chargeAnimStartTime = UnityEngine.Random.Range(0.5f, 0.75f);
			currentPK.skillLevel = ((!isUltimate) ? (-1) : skillLevelList[i]);
			currentPK.isUltimate = isUltimate;
			currentPK.playerSummonsList = parent.playerSummonsList;
			currentPK.targetRange = 10f;
			spawnPosition += Vector2.up;
