			ChaosBurst.Spawn(spawnPosition, 5);
		}
		SoundManager.PlayWithDistAndSPR("ChaosBeamStart", currentPosition);
		CameraController.ShakeCamera(0.5f);
	}

	private void SyncUltSkillData()
	{
		foreach (KeyValuePair<string, SyncedNumVarStat> item in skillData.numVarStatDict)
		{
			ultSkillData.EnsureVarStatEntry(item.Key);
			ultSkillData.numVarStatDict[item.Key].modifiers = item.Value.modifiers;
			ultSkillData.numVarStatDict[item.Key].Recalculate();
		}
	}
}

