	public override void Update()
	{
		if (resetQueued)
		{
			if (ChaosStopwatch.Check(resetStopwatchID))
			{
				Reset();
			}
		}
		else
		{
			if (!dashCompleted)
			{
				return;
			}
			SetXScale();
			if (!ChaosStopwatch.Check(delayStopwatchID))
