		{
			targetInfo = Entity.GetTargetInfoFromObject(targetList[Random.Range(0, targetList.Count)]);
			targetList.Clear();
			if (targetInfo != null && arrowSpawn != null)
			{
				return true;
			}
		}
		return false;
	}

	private void AimTowardsTarget(bool useTimer = true)
	{
		if (currentProj != null)
		{
			currentProj.transform.position = arrowSpawn.position;
		}
		if ((!useTimer || !aimStopwatch.IsRunning) && targetInfo != null && !(targetInfo.transform == null) && !(targetInfo.hurtBoxTransform == null))
		{
			aimStopwatch.IsRunning = useTimer;
			FaceTarget(targetInfo.transform.position, 2);
			SetXScale();
			aimVector = (targetInfo.hurtBoxTransform.position - arrowSpawn.position).normalized;
			roteVector = Globals.GetRotationVector(aimVector);
			armVector = roteVector;
			if (!isFacingRight)
			{
				armVector.z *= -1f;
			}
			armVector.z += 90f;
			if (bowArm != null)
			{
				bowArm.localEulerAngles = armVector;
			}
			if (!(currentProj == null))
			{
				currentProj.RefreshFlightTime();
				currentProj.transform.localEulerAngles = roteVector;
			}
		}
	}

	private void CreateSpreadShot()
	{
		currentPos = (Vector2)arrowSpawn.position - aimVector * 0.5f;
		for (int i = 0; i < 5; i++)
		{
			CreateProjectile(currentPos, Globals.GetRotatedCircleVector(24, i - 2, aimVector), skillLv, release: true);
		}
	}

	private void CreateProjectile(Vector2 givenPos, Vector2 givenVec, int givenLv, bool release = false)
	{
		currentProj = Projectile.CreateProjectile(parentEnt, ProjPrefab, givenPos, Globals.GetRotationQuaternion(givenVec));
		currentProj.attackBox.SetAttackInfo(skillCategory, skillID, givenLv);
		currentProj.Show();
		currentProj.attackBox.gameObject.SetActive(value: false);
		currentProj.wallCollider.gameObject.SetActive(value: false);
		if (release)
		{
			ReleaseProjectile(currentProj, givenVec, givenDisable: false);
			currentProj = null;
		}
	}

	private void ReleaseProjectile(Projectile givenProj, Vector2 givenVec, bool givenDisable = true)
	{
		if (!(givenProj == null))
		{
			givenProj.transform.localEulerAngles = Globals.GetRotationVector(givenVec);
			givenProj.moveVector = givenVec;
			givenProj.attackBox.knockbackOverwriteVector = givenVec;
			givenProj.attackBox.gameObject.SetActive(value: true);
			givenProj.wallCollider.gameObject.SetActive(value: true);
			SoundManager.PlayAudioWithDistance("ArcherAttackRelease", transform.position);
			SoundManager.PlayAudioWithDistance("ArcherArrow", transform.position);
			givenProj.moveSpeed = 40f;
			givenProj.flyTime = 0.3f;
			givenProj.RefreshFlightTime();
			givenProj.goThroughWalls = false;
			givenProj.disableOnHit = givenDisable;
			givenProj.projectileSpriteRenderer.material.SetColor("_OutlineColor", new Color(1f, 1f, 1f, 0.1f));
		}
	}

	private void EndAttack()
	{
		anim.Play("GroundSlam", -1, 0.3f);
		resetStopwatchID = ChaosStopwatch.Begin(0.25f);
		resetQueued = true;
		currentPos = transform.position + Vector3.up;
		PoolManager.GetPoolItem<ParticleEffect>("ChaosLightningBurst").Emit(3, currentPos);
		SoundManager.PlayWithDistAndSPR("ChaosLightningCrackle", currentPos);
	}

	private void Reset()
	{
		currentPos = transform.position + Vector3.up;
		PoolManager.GetPoolItem<ParticleEffect>("ChaosChargeEffect").Emit(3, currentPos, ParticleEffectOverrides.StartLifeTime0p25);
		PoolManager.GetPoolItem<AnimEffect>("ChaosPortal").Play(currentPos, "Depart");
		string audioID = "EnemyDead";
		Vector2? soundOrigin = currentPos;
		float overridePitch = Random.Range(1.1f, 1.2f);
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
		Object.Destroy(gameObject);
	}
}
