			throwScript.throwHeight += 0.5f;
		}
	}

	private void CreatePillar()
	{
		ChaosPillar chaosPillar = Globals.ChaosInst<ChaosPillar>(ChaosPillar.Prefab, null, transform.position + Vector3.up * 0.25f);
