		chaosPillar.readyTime = 0.0625f;
		chaosPillar.maxHitCount = 1;
		chaosPillar.hitInterval = 0.125f;
		chaosPillar.useCastCircle = false;
		chaosPillar.useChargeEffect = false;
		chaosPillar.playSFXOnInterval = true;
	}

	private void CreateCircle()
	{
		ChaosCircle chaosCircle = Globals.ChaosInst<ChaosCircle>(ChaosCircle.Prefab, null, transform.position + Vector3.up * 0.5f);
