		chaosCircle.finalAttackLevel = 3;
		chaosCircle.attackDuration = 0.225f;
		chaosCircle.hitInterval = 0.125f;
		chaosCircle.maxHitCount = 3;
	}

	private void EndAttack()
	{
		anim.Play("PointUp", -1, 0.35f);
		resetStopwatchID = ChaosStopwatch.Begin(0.25f);
		resetQueued = true;
		currentPosition = transform.position + Vector3.up;
		PoolManager.GetPoolItem<ParticleEffect>("ChaosLightningBurst").Emit(5, currentPosition);
		SoundManager.PlayWithDistAndSPR("ChaosLightningCrackle", currentPosition);
	}

	private void Reset()
	{
		currentPosition = transform.position + Vector3.up;
		PoolManager.GetPoolItem<ParticleEffect>("ChaosChargeEffect").Emit(3, currentPosition, ParticleEffectOverrides.StartLifeTime0p25);
		PoolManager.GetPoolItem<AnimEffect>("ChaosPortal").Play(currentPosition, "Depart");
		string audioID = "EnemyDead";
		Vector2? soundOrigin = currentPosition;
		float overridePitch = UnityEngine.Random.Range(1.1f, 1.2f);
