using System.Collections.Generic;
using Chaos.ListExtensions;
using UnityEngine;

public class PhantomSummoner : Entity
{
	private static GameObject prefab;

	public Transform bodyTrans;

	[HideInInspector]
	public Entity parentEnt;

	[HideInInspector]
	public List<GameObject> playerSummonsList;

	[HideInInspector]
	public string skillID = string.Empty;

	[HideInInspector]
	public Vector2 atkVector;

	private Vector2 currentPos;

	private int delayStopwatchID;

	private int destroyStopwatchID;

	private bool spawnCompleted;

	private bool atkStarted;

	private bool destroyQueued;

	private int maxAtkCount = 3;

	private PhantomOrb currentPO;

	private List<PhantomOrb> orbList = new List<PhantomOrb>();

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Effects/PhantomSummoner.prefab"));

	private bool OrbsExist
	{
		get
		{
			orbList.RemoveNullValues();
			return orbList.Count > 0;
		}
	}

	public override void Awake()
	{
		disablePreventFallCollider = true;
		base.Awake();
	}

	public override void Start()
	{
		base.Start();
		maxAtkCount = ((!Globals.RandBool) ? 3 : 4);
		FaceTarget(transform.position + (Vector3)atkVector, 2);
		SetXScale();
		anim.Play("Multicast", -1, 0f);
		delayStopwatchID = ChaosStopwatch.Begin(Random.Range(0.15f, 0.3f));
		spriteRenderer.material.SetColor("_OutlineColor", new Color(1f, 1f, 1f, 0.2f));
		currentPos = bodyTrans.position;
		PoolManager.GetPoolItem<ParticleEffect>("ChaosLightningBurst").Emit(4, currentPos);
		PoolManager.GetPoolItem<AnimEffect>("ChaosPortal").Play(currentPos, "Spawn");
		ChaosBurst.Spawn(currentPos, 3);
	}

	public override void Update()
	{
		if (destroyQueued)
		{
			if (ChaosStopwatch.Check(destroyStopwatchID))
			{
				DestroySummoner();
			}
			return;
		}
		SetXScale();
		if (!ChaosStopwatch.Check(delayStopwatchID))
		{
			return;
		}
		if (!spawnCompleted)
		{
			spawnCompleted = true;
			currentPos = transform.position;
			for (int i = 0; i < 3; i++)
			{
				CreateOrb(currentPos, Globals.GetRotatedCircleVector(3, i, atkVector));
			}
		}
		else if (!atkStarted)
		{
			atkStarted = true;
			if (OrbsExist)
			{
				QueueOrbAttack();
			}
			else
			{
				QueueDestroy();
			}
		}
		else if (maxAtkCount > 0)
		{
			maxAtkCount--;
			atkStarted = maxAtkCount < 1;
			delayStopwatchID = ChaosStopwatch.Begin(Random.Range(0.5f, 0.625f));
		}
		else
		{
			QueueDestroy();
		}
	}

	private void CreateOrb(Vector2 givenPos, Vector2 givenVec)
	{
		currentPO = Globals.ChaosInst<PhantomOrb>(PhantomOrb.Prefab, null, Globals.GetSafeLinecastVector(givenPos, givenVec, 1.5f, ChaosCollisions.layerAllWallAndObst));
		currentPO.parentObj = parentEnt.gameObject;
		currentPO.attack.SetAttackInfo(skillCategory, skillID);
		orbList.Add(currentPO);
	}

	private void QueueOrbAttack()
	{
		for (int i = 0; i < orbList.Count; i++)
		{
			if (orbList[i] != null)
			{
				orbList[i].Attack(maxAtkCount <= 1);
			}
		}
		if (maxAtkCount <= 1)
		{
			orbList.Clear();
		}
	}

	private void QueueDestroy()
	{
		if (!destroyQueued)
		{
			destroyQueued = true;
			destroyStopwatchID = ChaosStopwatch.Begin(0.25f);
			anim.Play("Cast", -1, 0f);
			movement.EndMovement();
			currentPos = bodyTrans.position;
			PoolManager.GetPoolItem<ParticleEffect>("ChaosLightningBurst").Emit(3, currentPos);
			SoundManager.PlayWithDistAndSPR("ChaosLightningCrackle", currentPos);
		}
	}

	private void DestroySummoner()
	{
		if (!(gameObject == null))
		{
			currentPos = bodyTrans.position;
			PoolManager.GetPoolItem<ParticleEffect>("ChaosChargeEffect").Emit(3, currentPos, ParticleEffectOverrides.StartLifeTime0p25);
			AnimEffect poolItem = PoolManager.GetPoolItem<AnimEffect>("ChaosPortal");
			Vector3 position = currentPos;
			string animName = "Depart";
			Vector3? localEulerAngles = new Vector3(0f, 0f, Random.Range(0f, 360f));
			poolItem.Play(position, animName, 0f, default, 1f, 1f, localEulerAngles);
			animName = "EnemyDead";
			Vector2? soundOrigin = currentPos;
			float overridePitch = Random.Range(1.1f, 1.2f);
			SoundManager.PlayAudioWithDistance(animName, soundOrigin, null, 24f, -1f, overridePitch);
			orbList.Clear();
			Object.Destroy(gameObject);
		}
	}
}
