	public Attack atkBox;

	private Vector2 initDashVec;

	private Vector2 currentPos;

	private int delayStopwatchID;

	private bool dashCompleted;

	private bool atkStarted;

	private bool atkCompleted;

	private bool animPlayed;

	private bool destroyQueued;

	private bool targetHit;

	private Entity targetEntity;

	private Vector2 atkVector;

	private Vector3 roteVector;

	private ChaosQuickStopwatch destroyStopwatch = new ChaosQuickStopwatch(0.25f);

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Effects/PhantomRogue.prefab"));

	public override void Awake()
	{
		disablePreventFallCollider = true;
		base.Awake();
	}

	public override void Start()
	{
		base.Start();
		StartDash(initDashVec);
		Attack attack = atkCircle;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		Attack attack2 = atkCircle;
		attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		atkCircle.knockbackOverwriteVector = initDashVec;
		atkCircle.collider.enabled = true;
		spriteRenderer.material.SetColor("_OutlineColor", new Color(1f, 1f, 1f, 0.2f));
		currentPos = bodyTrans.position;
		PoolManager.GetPoolItem<ParticleEffect>("ChaosLightningBurst").Emit(2, currentPos);
		PoolManager.GetPoolItem<AnimEffect>("ChaosPortal").Play(currentPos, "Spawn");
		SoundManager.PlayWithDistAndSPR("StandardDash", currentPos);
	}

	public override void Update()
	{
		if (destroyQueued)
		{
			if (!destroyStopwatch.IsRunning)
			{
				DestroyRogue();
			}
			else if (!animPlayed && destroyStopwatch.TimePercentage >= 0.6f)
			{
				animPlayed = true;
				anim.Play("StealthNoColorChange", -1, 0f);
			}
		}
		else
		{
			if (!dashCompleted)
			{
				return;
			}
			SetXScale();
			if (!ChaosStopwatch.Check(delayStopwatchID))
			{
				return;
			}
			if (!atkStarted)
			{
				atkStarted = true;
				if (!targetHit)
				{
					anim.Play("Crouch", -1, 1f);
					QueueDestroy();
					return;
				}
				if (targetEntity.hurtBoxTransform != null)
				{
					atkVector = (targetEntity.hurtBoxTransform.position - atkBox.transform.position).normalized;
				}
				FaceTarget(transform.position + (Vector3)atkVector, 2);
				SetXScale();
				anim.Play("Attack", -1, 0.4f);
				atkBox.knockbackOverwriteVector = atkVector;
				roteVector = Globals.GetRotationVector(atkVector);
				if (!isFacingRight)
				{
					roteVector.z *= -1f;
				}
				atkBox.transform.localEulerAngles = roteVector;
				delayStopwatchID = ChaosStopwatch.Begin(0.1f);
				string audioID = "RogueAttack";
				Vector2? soundOrigin = transform.position;
				float overridePitch = UnityEngine.Random.Range(1f, 1.1f);
				SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
			}
			else if (!atkCompleted)
			{
				atkCompleted = true;
				atkStarted = false;
				atkBox.ChangeAttackInfoLevel(3);
			}
			else
			{
				animPlayed = true;
				movement.dashSpeedStat.SetInitialBaseValue(10f);
				movement.dashDurationStat.SetInitialBaseValue(0.2f);
				StartDash(-atkVector, isReverse: true);
				destroyStopwatch.SetDelay(0.15f);
				QueueDestroy();
			}
		}
	}

	public override void FixedUpdate()
	{
		if (dashCompleted || !movement.DashToTarget())
		{
			return;
		}
		dashCompleted = true;
		if (destroyQueued)
		{
			DestroyRogue();
			return;
		}
		anim.Play("Crouch", -1, 1f);
		atkCircle.collider.enabled = false;
		Attack attack = atkCircle;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		if (!targetHit)
		{
			movement.moveVector = initDashVec;
			movement.MoveToMoveVector();
		}
	}

	private void StartDash(Vector3 givenVec, bool isReverse = false)
	{
		FaceTarget(transform.position + ((!isReverse) ? givenVec : (-givenVec)), 2);
		SetXScale();
		anim.Play((!isReverse) ? "Dash" : "BackDash", -1, 0f);
		movement.dashVector = givenVec;
		dashCompleted = false;
