using UnityEngine;

public class PhantomMage : Entity
{
	private static GameObject prefab;

	private static GameObject projPrefab;

	private static Color phantomColor = new Color(0.4f, 0.4f, 1f, 0.2f);

	public Transform bodyTrans;

	private Vector2 atkVec;

	private Vector2 currentPos;

	private string skillID = string.Empty;

	private int delayStopwatchID;

	private int destroyStopwatchID;

	private bool atkStarted;

	private bool destroyQueued;

	private EnemyFireball currentEF;

	private Entity parentEntity;

	private int maxAtkCount = 3;

	private bool flipForced;

	private bool isFlipped;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Effects/PhantomMage.prefab"));

	public static GameObject ProjPrefab => projPrefab ?? (projPrefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/PhantomFireball.prefab"));

	public override void Awake()
	{
		disablePreventFallCollider = true;
		base.Awake();
	}

	public override void Start()
	{
		base.Start();
		currentPos = bodyTrans.position;
		FaceTarget(currentPos + atkVec, 2);
		SetXScale();
		anim.Play("CastAlt", -1, 0f);
		delayStopwatchID = ChaosStopwatch.Begin(0.25f);
		spriteRenderer.material.SetColor("_OutlineColor", new Color(1f, 1f, 1f, 0.4f));
		PoolManager.GetPoolItem<ParticleEffect>("ChaosLightningBurst").Emit(3, currentPos);
		PoolManager.GetPoolItem<AnimEffect>("ChaosPortal").Play(currentPos, "Spawn");
		ChaosBurst.Spawn(currentPos, 3);
	}

	public override void Update()
	{
		if (destroyQueued)
		{
			if (ChaosStopwatch.Check(destroyStopwatchID))
			{
				DestroyMage();
			}
			return;
		}
		SetXScale();
		if (!ChaosStopwatch.Check(delayStopwatchID))
		{
			return;
		}
		if (!atkStarted)
		{
			atkStarted = true;
			anim.Play("PBAoE", -1, 1f);
			currentPos = bodyTrans.position;
			switch (maxAtkCount)
			{
			case 1:
			{
				for (int j = -1; j <= 1; j++)
				{
					CreateFireball(currentPos, Globals.GetRotatedCircleVector(15, j, atkVec));
				}
				break;
			}
			case 2:
			{
				for (int k = 6; k < 10; k++)
				{
					CreateFireball(currentPos, Globals.GetRotatedCircleVector(15, k, -atkVec));
				}
				break;
			}
			case 3:
			{
				for (int i = -2; i <= 2; i++)
				{
					CreateFireball(currentPos, Globals.GetRotatedCircleVector(15, i, atkVec));
				}
				break;
			}
			}
			SoundManager.PlayAudioWithDistance("MageFireballRelease", currentPos);
			delayStopwatchID = ChaosStopwatch.Begin(0.15f);
			return;
		}
		maxAtkCount--;
		if (maxAtkCount > 0)
		{
			atkStarted = false;
			anim.Play("CastAlt", -1, 0f);
			return;
		}
		if (flipForced)
		{
			facingDirection = (isFlipped ? FacingDirection.Right : FacingDirection.Left);
			SetXScale();
		}
		anim.Play("Raise", -1, 0.35f);
		QueueDestroy();
	}

	private void CreateFireball(Vector2 givenPos, Vector2 givenVec)
	{
		currentEF = (EnemyFireball)Projectile.CreateProjectile(parentEntity, ProjPrefab, givenPos + givenVec, Globals.GetRotationQuaternion(givenVec));
		currentEF.attackBox.SetAttackInfo(skillCategory, skillID);
		currentEF.attackBox.collider.enabled = true;
		currentEF.attackBox.knockbackOverwriteVector = givenVec;
		currentEF.moveVector = givenVec;
		currentEF.SetColor(3);
		currentEF.anim.Play("Idle", -1, 0f);
		currentEF.projectileSpriteRenderer.color = phantomColor;
		currentEF.projectileSpriteRenderer.material.SetColor("_OutlineColor", new Color(1f, 1f, 1f, 0.1f));
		currentEF.Show();
	}

	private void QueueDestroy()
	{
		if (!destroyQueued)
		{
			destroyQueued = true;
			destroyStopwatchID = ChaosStopwatch.Begin(0.25f);
		}
	}

	private void DestroyMage()
	{
		if (!(gameObject == null))
		{
			currentPos = bodyTrans.position;
			PoolManager.GetPoolItem<ParticleEffect>("ChaosLightningBurst").Emit(2, currentPos);
			PoolManager.GetPoolItem<ParticleEffect>("ChaosChargeEffect").Emit(1, currentPos, ParticleEffectOverrides.StartLifeTime0p25);
			PoolManager.GetPoolItem<AnimEffect>("ChaosPortal").Play(currentPos, "Depart", 0.3f);
			string audioID = "ChaosLightningCrackle";
			Vector2? soundOrigin = currentPos;
			float standardPitchRange = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, 0.2f, standardPitchRange);
			audioID = "EnemyDead";
			soundOrigin = currentPos;
			standardPitchRange = Random.Range(1.1f, 1.2f);
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, 0.2f, standardPitchRange);
			Object.Destroy(gameObject);
		}
	}

	public static PhantomMage Create(Entity givenEnt, Vector2 givenPos, Vector2 givenVec, string givenCat, string givenID, bool forceFlip, bool givenFlip)
	{
		PhantomMage phantomMage = Globals.ChaosInst<PhantomMage>(Prefab, null, givenPos);
		phantomMage.parentEntity = givenEnt;
		phantomMage.atkVec = givenVec;
		phantomMage.skillCategory = givenCat;
		phantomMage.skillID = givenID;
		phantomMage.flipForced = forceFlip;
		phantomMage.isFlipped = givenFlip;
		return phantomMage;
	}
}
