	public GameObject parentObj;

	[HideInInspector]
	public List<GameObject> playerSummonsList;

	private List<GameObject> targetList;

	private TargetInfo targetInfo;

	private float windLerpValue;

	private int windupStopwatchID;

	private int destroyStopwatchID = -1;

	private int lifeStopwatchID;

	private Vector2 currentPos;

	private Vector2 atkVector;

	private float originAngle;

	private float targetAngle;

	private bool atkStarted;

	private bool atkCompleted;

	private bool roteCompleted;

	private bool destroyQueued;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Effects/PhantomOrb.prefab"));

	public override void Awake()
	{
		disablePreventFallCollider = true;
		base.Awake();
	}

	public override void Start()
	{
		anim.Play("ChargeWindup", -1, 0f);
		originAngle = spriteRenderer.transform.localEulerAngles.z;
		currentPos = bodyTrans.position;
		ChaosBurst.Spawn(currentPos, 5);
		SoundManager.PlayWithDistAndSPR("ChaosFormShort", currentPos);
		spriteRenderer.material.SetColor("_OutlineColor", new Color(1f, 1f, 1f, 0.2f));
		lifeStopwatchID = ChaosStopwatch.Begin(8f);
	}

	public override void Update()
	{
		if (!destroyQueued && ChaosStopwatch.Check(lifeStopwatchID))
		{
			DestroyOrb();
		}
		else if (!atkCompleted)
		{
			if (!roteCompleted)
			{
				windLerpValue = ChaosStopwatch.GetTimePercentage(windupStopwatchID);
				anim.Play("ChargeWindup", -1, windLerpValue);
				spriteRenderer.transform.localEulerAngles = new Vector3(0f, 0f, Mathf.Lerp(originAngle, targetAngle, windLerpValue));
				roteCompleted = windLerpValue >= 1f;
			}
			else if (!atkStarted)
			{
				atkStarted = true;
				attack.collider.enabled = true;
				SoundManager.PlayWithDistAndSPR("ChaosFormShort", bodyTrans.position);
			}
		}
		else if (destroyQueued && ChaosStopwatch.Check(destroyStopwatchID))
		{
			DestroyOrb();
		}
	}

	public override void FixedUpdate()
	{
		if (atkStarted && !atkCompleted && movement.DashToTarget())
		{
			atkCompleted = true;
			anim.Play("ChargeWinddown", -1, 0f);
			movement.EndMovement();
			movement.MoveToMoveVector(10f);
			attack.collider.enabled = false;
			if (destroyQueued)
			{
				destroyStopwatchID = ChaosStopwatch.Begin(0.4f);
			}
		}
	}

	public void DestroyOrb()
	{
		if (!(gameObject == null))
		{
			currentPos = bodyTrans.position;
			ChaosBurst.Spawn(currentPos, 5);
			PoolManager.GetPoolItem<ParticleEffect>("ChaosLightningBurst").Emit(3, currentPos);
			SoundManager.PlayWithDistAndSPR("ChaosLightningCrackle", currentPos);
			string audioID = "TornadoEnd";
			Vector2? soundOrigin = currentPos;
			float overridePitch = Random.Range(1.1f, 1.2f);
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, 0.15f, overridePitch);
			Object.Destroy(gameObject);
		}
	}

	public void Attack(bool givenDestroy = false)
	{
		if (!FindTarget())
		{
			DestroyOrb();
			return;
		}
		atkStarted = false;
		atkCompleted = false;
		roteCompleted = false;
		destroyQueued = givenDestroy;
		movement.EndMovement();
		movement.moveVector = atkVector;
		movement.dashVector = atkVector;
		attack.knockbackOverwriteVector = atkVector;
		originAngle = spriteRenderer.transform.localEulerAngles.z;
		targetAngle = Globals.GetRotationVector(atkVector).z;
		windupStopwatchID = ChaosStopwatch.Begin(Random.Range(0.15f, 0.25f));
		string audioID = "LaserOrbWindup";
		Vector2? soundOrigin = bodyTrans.position;
		float standardPitchRange = SoundManager.StandardPitchRange;
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, 0.1f, standardPitchRange);
	}

	private bool FindTarget()
	{
		targetList = Entity.GetAllTargetsInRange(GameController.enemies, transform.position, 9f, playerTagOnly: false, playerSummonsList, parentObj, requireLOS: true, ChaosCollisions.layerAllWallAndObst);
		if (targetList != null && targetList.Count > 0)
		{
			targetInfo = Entity.GetTargetInfoFromObject(targetList[Random.Range(0, targetList.Count)]);
			targetList.Clear();
			if (targetInfo != null)
			{
				atkVector = (targetInfo.position - transform.position).normalized;
				return true;
			}
		}
		return false;
	}
}

