	public class CloneIdleState : State<ChaosClone>
	{
		private int delayStopwatchID;

		private bool queueDash;

		public CloneIdleState(string newName, FSM newFSM, ChaosClone newClone)
			: base(newName, newFSM, newClone)
		{
		}

		public override void OnEnter()
		{
			parent.PlayAnim("Idle");
			parent.movement.EndMovement();
			queueDash = parent.DashAvailable;
			delayStopwatchID = ((!queueDash) ? (-1) : ChaosStopwatch.Begin(1f + UnityEngine.Random.Range(-0.125f, 0.25f)));
		}

		public override void Update()
		{
			if (ChaosStopwatch.Check(delayStopwatchID))
			{
				if (parent.parentPlayer == null || !queueDash)
				{
					fsm.ChangeState("Dead");
					return;
				}
				parent.dashToParent = true;
				fsm.ChangeState("Dash");
			}
		}
	}

	public class CloneMoveState : State<ChaosClone>
	{
		protected string enterAnimStr = string.Empty;

		private string exitStateName = string.Empty;

		private ChaosQuickStopwatch moveStopwatch = new ChaosQuickStopwatch();

		private NumVarStatMod speedMod = new NumVarStatMod("ChaosClone", 1f, 10, VarStatModType.Override);

		public CloneMoveState(string newName, FSM newFSM, ChaosClone newClone, string givenEnter, string givenExit, float givenTime, float givenSpeed)
			: base(newName, newFSM, newClone)
		{
			enterAnimStr = givenEnter;
			exitStateName = givenExit;
			moveStopwatch.SetDelay(givenTime);
			speedMod.modValue = givenSpeed;
		}

		public override void OnEnter()
		{
			parent.PlayAnim(enterAnimStr);
			parent.movement.moveSpeedStat.AddMod(speedMod);
			moveStopwatch.IsRunning = true;
		}

		public override void FixedUpdate()
		{
			if (moveStopwatch.IsRunning)
			{
				parent.movement.MoveToMoveVector();
			}
			else
			{
				ExitTransition();
			}
		}

		public override void OnExit()
		{
			parent.movement.moveSpeedStat.RemoveMod(speedMod);
			parent.movement.EndMovement();
		}

		public virtual void ExitTransition()
		{
			fsm.ChangeState(exitStateName);
		}
	}

	public class CloneSlideState(string newName, FSM newFSM, ChaosClone newClone) : CloneMoveState(newName, newFSM, newClone, "Slide", "Idle", 0.3f, 10f)
	{
		public string exitStateName = "Dash";

		private bool firstSlide = true;

		public override void OnEnter()
