public class ProjectileChainAttackState : ProjectileAttackState
{
	public float shotDelay = 0.125f;

	public int shotStopwatchID;

	public bool attackStarted;

	public bool firstAnim;

	public bool updateInput = true;

	private Vector2 checkAimVec;

	public ProjectileChainAttackState(string newName, FSM newFSM, Player newPlayer)
		: base(newName, newFSM, newPlayer)
	{
		disableStartCooldown = true;
		isHoldSkill = true;
		InitChargeSkillSettings(skillData.GetValue<int>(StatData.spawnStr), 0f, skillData, this);
	}

	public override void OnEnter()
	{
		base.OnEnter();
		UpdateCDCounter();
		attackStarted = false;
		firstAnim = true;
	}

	public override void HandleHoldButton()
	{
		if (!StartAttack())
		{
			return;
		}
		switch (ChaosStopwatch.CheckInterval(shotStopwatchID))
		{
		case StopwatchState.Ready:
			if (firstAnim)
			{
				firstAnim = false;
				AnnounceSkillExecuteEvent();
			}
			else if (updateInput)
			{
				checkAimVec = GetInputVector(faceInputVector: false, useAimVector: true, ignoreZero: false);
				if (checkAimVec != Vector2.zero)
				{
					inputVector = GetInputVector(faceInputVector: true, useAimVector: true, ignoreZero: false);
				}
				parent.anim.PlayDirectional(OnHoldAnimStr, -1, animExecTime);
			}
			if (cooldownRef.chargeCount > 0)
			{
				cooldownRef.chargeCount--;
			}
			if (!cooldownRef.IsCharging)
			{
				UpdateCDCounter();
			}
			FireChainProjectile();
			break;
		case StopwatchState.Done:
			skillExecuted = true;
			break;
		}
		CancelToDash();
	}

	public override void OnExit()
	{
		base.OnExit();
		StartCooldownTimer(-1f, expendCharge: false);
		ChaosStopwatch.Stop(shotStopwatchID);
	}

	public virtual void UpdateCDCounter()
	{
		StartCooldownTimer(-1f, expendCharge: false);
		ChaosStopwatch.Pause(cooldownRef.remainingTimeStopwatchID);
	}

	public virtual bool StartAttack()
	{
		if (!attackStarted)
		{
			if (!parent.anim.AnimPlayed(animExecTime))
			{
				return false;
			}
			attackStarted = true;
			shotStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, shotDelay, cooldownRef.chargeCount);
		}
		return true;
	}

	public virtual void FireChainProjectile()
	{
	}
}

public class ProjectileChargeAttackState(string newName, FSM newFSM, Player newPlayer) : ProjectileHoldAttackState(newName, newFSM, newPlayer)
{
	public bool useCastBar = true;

	public class UseMortalCoil : ProjectileAttackState
	{
		public new static string staticID = "UseMortalCoil";

		private const int MCIndexMax = 3;

		private int mcIndexCount;

		private MortalCoil[] mcArray = new MortalCoil[3];

		private MortalCoil currentMC;

		private ChaosCircle currentCC;

		private Vector2 currentPosition;

		private bool atkAnimPlayed;

		private bool retAnimPlayed;

		public UseMortalCoil(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			hasSignatureVariant = true;
			empoweredStat.SetInitialBaseValue(newBaseVal: true);
			SetAnimTimes(0.1f);
		}

		public override void SetEmpowered(bool gs, BoolVarStatMod gm)
		{
		}

		public override void OnEnter()
		{
			BaseOnEnter();
			base.ExecuteSkill();
			inputVector = GetInputVector();
			parent.ToggleEnemyFloorCollisions(status: false);
			InitMortalCoil();
			atkAnimPlayed = false;
			retAnimPlayed = false;
		}

		public override void Update()
		{
			currentMC = GetActiveMC();
			if (currentMC == null)
			{
				ExitToSkillOrRunOrIdle();
				return;
			}
			if (!currentMC.attackStarted)
			{
				parent.anim.PlayDirectional(parent.ForehandAnimStr, -1, animStartTime);
			}
			if (!atkAnimPlayed && currentMC.attackStarted)
			{
				atkAnimPlayed = true;
				parent.anim.PlayDirectional(parent.ForehandAnimStr, -1, animExecTime);
			}
			if (!retAnimPlayed && currentMC.attackComplete)
			{
				retAnimPlayed = true;
				parent.anim.PlayDirectional(parent.BackhandAnimStr, -1, animExecTime);
				if (isUltimate)
				{
					CreateChaosStorm();
				}
			}
			if (!CancelToDash() && currentMC.attackComplete && !currentMC.delayStopwatch.IsRunning && !currentMC.returnStopwatch.IsRunning)
			{
				ExitToSkillOrRunOrIdle();
			}
		}

		public override void OnExit()
		{
			base.OnExit();
			parent.ToggleEnemyFloorCollisions();
			for (int i = 0; i < 3; i++)
			{
				if (mcArray[i] != null)
				{
					UnityEngine.Object.Destroy(mcArray[i].gameObject);
				}
			}
		}

		private MortalCoil GetActiveMC()
		{
			for (int i = 0; i < mcIndexCount; i++)
			{
				if (mcArray[i] != null)
				{
					return mcArray[i];
				}
			}
			return null;
		}

		private void InitMortalCoil()
		{
			currentPosition = parent.attackOriginTrans.position;
			mcIndexCount = ((!isUltimate) ? 1 : 3);
			for (int i = 0; i < mcIndexCount; i++)
			{
				currentMC = Globals.ChaosInst<MortalCoil>(MortalCoil.Prefab, parent.attackOriginTrans, currentPosition);
				if (isUltimate)
				{
					currentMC.Initialize(currentPosition, Globals.GetRotatedCircleVector(24, i - 1, inputVector), parent.skillCategory, skillID, givenUlt: true, parent.attackOriginTrans, 14f);
				}
				else
				{
					currentMC.Initialize(currentPosition, inputVector, parent.skillCategory, skillID, givenUlt: false, parent.attackOriginTrans);
				}
				currentMC.delayStopwatchTime = 0.125f;
				mcArray[i] = currentMC;
			}
		}

		private void CreateChaosStorm()
		{
			currentCC = ChaosInst<ChaosCircle>(ChaosCircle.Prefab, parent.attackOriginTrans.position);
			currentCC.attack.SetAttackInfo(parent.skillCategory, skillID, 3, isUltimate);
			currentCC.finalAttackLevel = 4;
			currentCC.attackDuration = 1.5f;
			currentCC.hitInterval = 0.1f;
			currentCC.maxHitCount = 11;
		}
	}

