using System;
using UnityEngine;

public class MortalCoil : MonoBehaviour
{
	private static GameObject prefab;

	private MortalCoilProjectile mortalCoilProj;

	private ChaosQuickStopwatch attackStopwatch = new ChaosQuickStopwatch(0.125f);

	public ChaosQuickStopwatch returnStopwatch = new ChaosQuickStopwatch(3f);

	public ChaosQuickStopwatch delayStopwatch;

	public bool goThroughWalls;

	public float returningSnapDistance = 2f;

	public float delayStopwatchTime = 0.125f;

	private float attackDiameter = 1f;

	public float attackRange = 8f;

	public bool attackStarted;

	public bool attackCreated;

	public bool attackComplete;

	private bool lightningEffectPlayed;

	private string skillID = string.Empty;

	private string skillCategory = string.Empty;

	private bool skillIsUltimate;

	private Vector2 lineStartPos;

	private Vector2 lineEndPos;

	private float lineLength;

	private Vector2 attackVec;

	private Transform parentTrans;

	private bool attackColliderFrameSkipped;

	public Attack attackBox;

	private SectionedTrailEmitter curTrailEmitter;

	private ChaosQuickStopwatch returnUpdateStopWatch;

	private float returnUpdateTime = 0.02f;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/MortalCoil.prefab"));

	private void Awake()
	{
		attackBox = transform.Find("AttackBox").GetComponent<Attack>();
	}

	public void Initialize(Vector3 startPosition, Vector2 attackVector, string givenCategory, string givenID, bool givenUlt, Transform parentTransform = null, float atkRange = 8f)
	{
		lineStartPos = startPosition;
		attackVec = attackVector;
		attackStarted = false;
		attackCreated = false;
		attackComplete = false;
		lightningEffectPlayed = false;
		attackRange = atkRange;
		returnUpdateStopWatch = new ChaosQuickStopwatch(returnUpdateTime);
		delayStopwatch = new ChaosQuickStopwatch(delayStopwatchTime);
		attackStopwatch.IsRunning = true;
		skillID = givenID;
		skillCategory = givenCategory;
		skillIsUltimate = givenUlt;
		parentTrans = parentTransform;
	}

	private void FixedUpdate()
	{
		if (attackBox.collider.enabled)
		{
			if (!attackColliderFrameSkipped)
			{
				attackColliderFrameSkipped = true;
			}
			else
			{
				attackBox.collider.enabled = false;
			}
		}
	}

	private void Update()
	{
		if (!attackStarted)
		{
			if (attackStopwatch.IsRunning)
			{
				return;
			}
			attackStarted = true;
		}
		if (!attackCreated)
		{
			SetLineVars();
			InitAttackBox();
			CreateMortalCoilProj(lineEndPos);
			CameraController.ShakeCamera();
			PoolManager.GetPoolItem<SectionedTrailEmitter>("ChaosLightningTrail").Emit(lineStartPos, lineEndPos - (lineEndPos - lineStartPos).normalized, -1, emitEveryOther: true);
			PoolManager.GetPoolItem<SectionedTrailEmitter>("ChaosWireTrail").Emit(lineStartPos, lineEndPos);
			delayStopwatch.IsRunning = true;
			attackCreated = true;
		}
		if (!attackComplete)
		{
			ReadjustTrailLength();
			if (!delayStopwatch.IsRunning)
			{
				returnStopwatch.IsRunning = true;
				attackComplete = true;
			}
		}
		else if (mortalCoilProj != null && returnStopwatch.IsRunning)
		{
			if (!returnUpdateStopWatch.IsRunning)
			{
				ReadjustTrailLength();
			}
		}
		else
		{
			if (curTrailEmitter != null)
			{
				curTrailEmitter.effectEmitter.Clear();
			}
			UnityEngine.Object.Destroy(gameObject);
		}
	}

	private void SetLineVars()
	{
		lineEndPos = Globals.GetLinecastVector(lineStartPos, lineStartPos + attackVec * attackRange, ChaosCollisions.layerUpperWallAndObst);
		lineLength = Vector2.Distance(lineStartPos, lineEndPos);
	}

	private void InitAttackBox()
	{
		attackBox.transform.position = lineStartPos + attackVec * lineLength * 0.5f;
		attackBox.transform.rotation = Globals.GetRotationQuaternion(attackVec);
		(attackBox.collider as BoxCollider2D).size = new Vector2(attackDiameter, lineLength);
		attackBox.SetAttackInfo(skillCategory, skillID, 1, skillIsUltimate);
		attackBox.knockbackOverwriteVector = attackVec;
		attackBox.collider.enabled = true;
		attackColliderFrameSkipped = false;
	}

	public void ReadjustTrailLength()
	{
		if (mortalCoilProj.boomerangReturning && !returnUpdateStopWatch.IsRunning)
		{
			returnUpdateStopWatch.IsRunning = true;
			if (curTrailEmitter != null)
			{
				curTrailEmitter.effectEmitter.Clear();
			}
			curTrailEmitter = PoolManager.GetPoolItem<SectionedTrailEmitter>("ChaosWireTrail");
			curTrailEmitter.Emit(lineStartPos, mortalCoilProj.transform.position);
		}
	}

	private void OnDestroy()
	{
		if (curTrailEmitter != null)
		{
			curTrailEmitter.effectEmitter.Clear();
		}
		if (mortalCoilProj != null)
		{
			mortalCoilProj.ResetProjectile();
		}
		if (attackBox.collider.enabled)
		{
			attackBox.collider.enabled = false;
		}
	}

	private void CreateMortalCoilProj(Vector2 spawnPosition)
	{
		mortalCoilProj = Globals.ChaosInst<MortalCoilProjectile>(MortalCoilProjectile.Prefab, parentTrans, spawnPosition, Quaternion.identity);
		mortalCoilProj.attackBox.SetAttackInfo(skillCategory, skillID, 2, skillIsUltimate);
		mortalCoilProj.UpdateCalculatedDamage(initDamageOverride: true);
		MortalCoilProjectile mortalCoilProjectile = mortalCoilProj;
		mortalCoilProjectile.resetEventHandler = (MortalCoilProjectile.ResetEventHandler)Delegate.Combine(mortalCoilProjectile.resetEventHandler, new MortalCoilProjectile.ResetEventHandler(ProjectileReturned));
		mortalCoilProj.parentObject = parentTrans.gameObject;
		mortalCoilProj.moveVector = -attackVec;
		mortalCoilProj.delayStopwatchTime = delayStopwatchTime;
		mortalCoilProj.returningSnapDistance = returningSnapDistance;
		mortalCoilProj.goThroughWalls = goThroughWalls;
		ChaosBurst.Spawn(lineStartPos + attackVec, 5);
		SoundManager.PlayAudioWithDistance("ChaosFormLong", lineStartPos);
		SoundManager.PlayWithDistAndSPR("ChaosBeamStart", lineStartPos);
	}

	public void ProjectileReturned()
	{
		if (returnStopwatch.IsRunning && mortalCoilProj != null)
		{
			MortalCoilProjectile mortalCoilProjectile = mortalCoilProj;
			mortalCoilProjectile.resetEventHandler = (MortalCoilProjectile.ResetEventHandler)Delegate.Remove(mortalCoilProjectile.resetEventHandler, new MortalCoilProjectile.ResetEventHandler(ProjectileReturned));
			lineEndPos = mortalCoilProj.transform.position;
			PoolManager.GetPoolItem<SectionedTrailEmitter>("ChaosLightningTrail").Emit(lineStartPos, lineEndPos, -1, emitEveryOther: true);
		}
		returnStopwatch.IsRunning = false;
	}
}
