		}
	}

	public override void ResetProjectile()
	{
		base.ResetProjectile();
		if (resetEventHandler != null)
		{
			resetEventHandler();
		}
		hitTargetsList.Clear();
		hitPositionList.Clear();
		ChaosBurst.Spawn(transform.position, 5);
		string audioID = "EnemyDead";
		Vector2? soundOrigin = transform.position;
		float overridePitch = UnityEngine.Random.Range(1.1f, 1.2f);
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
	}

	private void OnTargetHit(Entity hitEntity)
	{
		if (!(hitEntity == null) && !(hitEntity is Destructible) && !(hitEntity.rigidbody2D == null) && hitEntity.rigidbody2D.bodyType == RigidbodyType2D.Dynamic && !hitEntity.health.ignoreGrab && !hitTargetsList.Contains(hitEntity))
		{
			hitTargetsList.Add(hitEntity);
			hitPositionList.Add(0.5f * ((Vector3)moveVector + (hitEntity.transform.position - transform.position).normalized));
		}
	}
}

