	projectileSpriteRenderer = projectileSprite.GetComponent<SpriteRenderer>();
	if (base.transform.Find("ProjectileLight") != null)
	{
		projectileLight = base.transform.Find("ProjectileLight").gameObject;
	}
	if (pointTowardMoveVector)
	{
		Hide();
	}
	OffsetSortingLayer();
	thickness = 0f;
	Transform transform = base.transform.Find("WallCollider");
	if (transform != null)
	{
		CircleCollider2D component = transform.gameObject.GetComponent<CircleCollider2D>();
		if (component != null)
		{
			thickness = component.radius * ((!(base.transform.localScale.x > base.transform.localScale.y)) ? base.transform.localScale.y : base.transform.localScale.x);
			wallCollider = component;
		}
		else
		{
			BoxCollider2D component2 = transform.gameObject.GetComponent<BoxCollider2D>();
			if (component2 != null)
			{
				thickness = component2.size.x * base.transform.localScale.x;
				wallCollider = component2;
			}
		}
	}
	if (thickness > 0f && (double)thickness < 0.0625)
	{
		thickness = 0.0625f;
	}
}

public virtual void InitTimers()
{
	flyStopwatchID = ChaosStopwatch.Begin(flyTime);
	lifeStopwatchID = ChaosStopwatch.Begin(lifeTime);
}

public virtual void Start()
{
	if (parentObject != null && parentEntity == null)
	{
		parentEntity = parentObject.GetComponentInParent<Entity>();
	}
	InitTimers();
	startAttackBoxDamageOverride = attackBox.damageOverride;
	UpdateCalculatedDamage(initDamageOverride: true);
	rotationVector = new Vector3(0f, 0f, rotationsPerSecond * 360f);
	if (projectileSpawnEvent != null)
	{
		projectileSpawnEvent(this);
	}
}

public void Show()
{
	visualsOn = true;
	projectileSpriteRenderer.enabled = true;
	if (projectileLight != null)
	{
		projectileLight.SetActive(value: true);
	}
}

public void Hide()
{
	visualsOn = false;
	projectileSpriteRenderer.enabled = false;
	if (projectileLight != null)
	{
		projectileLight.SetActive(value: false);
	}
}

private void OnEnable()
{
	targetGroup = GameController.enemies;
	InitTimers();
}

private void OnDisable()
{
	CallOnDisable();
}

public virtual void CallOnDisable()
{
	moveVector = Vector2.zero;
	isPointedAtMoveVector = false;
}

public virtual bool CheckMaxLifeTime()
{
	if (ChaosStopwatch.Check(lifeStopwatchID) || flagForReset)
	{
		ResetProjectile();
		return true;
	}
	return false;
}

public virtual void Update()
{
	if (!shootAnnounced && moveSpeed > 0f && moveVector != Vector2.zero && projectileShootEvent != null)
	{
		projectileShootEvent(this);
		shootAnnounced = true;
	}
	if (CheckMaxLifeTime())
	{
		return;
	}
	if (ChaosStopwatch.Check(flyStopwatchID))
	{
		if (!boomerang)
		{
			ResetProjectile();
			return;
		}
		if (parentObject == null)
		{
			boomerang = false;
			Debug.Log(gameObject.name + " has no parent, but is set to boomerang.");
			return;
		}
		if (!boomerangReturning)
		{
			boomerangReturning = true;
			OnBoomerangReturn();
			return;
		}
		if (attackBox != null && resetAttackOnBoomerangReturn)
		{
			attackBox.gameObject.SetActive(value: true);
		}
		HandleBoomerang();
	}
	if (boomerangReturning && (parentObject == null || Vector2.Distance(transform.position, parentObject.transform.position) < returningSnapDistance))
	{
		ResetProjectile();
	}
}

public virtual void FixedUpdate()
{
	if (updateVelocity)
	{
		rigidbody2D.velocity = moveVector * moveSpeed;
	}
	HandleRotation();
	HandlePointTowardMoveVector();
}

public virtual void HandleRotation()
{
	if (rotation)
	{
		projectileSprite.transform.Rotate(rotationVector * Time.fixedDeltaTime);
	}
}

public void HandlePointTowardMoveVector()
{
	if (pointTowardMoveVector && moveVector != Vector2.zero && !isPointedAtMoveVector)
	{
		Vector2 targetPosition = ((!flipPointTowardMoveVector) ? ((Vector2)transform.position + moveVector) : ((Vector2)transform.position - moveVector));
		RotateTowardsTarget(targetPosition);
		isPointedAtMoveVector = true;
	}
	if (pointTowardMoveVector && isPointedAtMoveVector && !visualsOn)
	{
		Show();
	}
}

