		private static float vsDelayIncrement = 0.125f;

		private int vsIndexCount;

		private static float openTime = 2f;

		private bool useDetonate;

		private Vector2 currentPosition;

		private Vector2 attackPosition;

		private Vector2 throwVector;

		private VoidShift ActiveVS
		{
			get
			{
				for (int i = 0; i < vsIndexCount; i++)
				{
					if (vsArray[i] != null)
					{
						return vsArray[i];
					}
				}
				return null;
			}
		}

		private bool DetonateAvailable
		{
			get
			{
				currentVS = ActiveVS;
				return currentVS != null && !currentVS.detonateQueued;
			}
		}

		public override string OnEnterAnimStr => (!useDetonate) ? parent.BackhandAnimStr : parent.PBAoEAnimStr;

		public UseVoidShift(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			hasSignatureVariant = true;
			empoweredStat.SetInitialBaseValue(newBaseVal: true);
			isProjectileSkill = false;
			disableStartCooldown = true;
			SetAnimTimes(0.25f, 0.2f, 0.3f, 0.5f, 0.55f);
			Player player = parent;
			player.onSurvivalRoomEnterHandlers = (OnSurvivalRoomEnterEventHandler)Delegate.Remove(player.onSurvivalRoomEnterHandlers, new OnSurvivalRoomEnterEventHandler(CleanUpVS));
			Player player2 = parent;
			player2.onSurvivalRoomEnterHandlers = (OnSurvivalRoomEnterEventHandler)Delegate.Combine(player2.onSurvivalRoomEnterHandlers, new OnSurvivalRoomEnterEventHandler(CleanUpVS));
		}

		public override void SetEmpowered(bool gs, BoolVarStatMod gm)
		{
		}

		public override void OnEnter()
		{
			if (isUltimate)
			{
				vsIndexCount = vsIndexMax;
				useDetonate = false;
				DetonateVS();
			}
			else
			{
				vsIndexCount = 1;
				useDetonate = DetonateAvailable;
			}
			base.OnEnter();
		}

		public override void ExecuteSkill()
		{
			base.ExecuteSkill();
			if (useDetonate)
			{
				parent.hud.castBar.EndCast();
				DetonateVS();
				return;
			}
			attackPosition = parent.attackOriginTrans.position;
			parent.hud.castBar.StartCast(ChaosStopwatch.Begin(openTime), givenStatus: false);
			PoolManager.GetPoolItem<ParticleEffect>("ChaosLightningBurst").Emit(3, attackPosition + inputVector * 0.5f);
			SoundManager.PlayWithDistAndSPR("ChaosLightningCrackle", attackPosition);
			CreateVoidShift();
			parent.StartCoroutine(HandleCooldown());
		}

		private void CreateVoidShift()
		{
			currentPosition = parent.transform.position;
			attackPosition = parent.attackOriginTrans.position;
			for (int i = 0; i < vsIndexCount; i++)
			{
				currentVS = ChaosInst<VoidShift>(VoidShift.Prefab, currentPosition);
				currentVS.attack.SetAttackInfo(parent.skillCategory, skillID, 1, isUltimate);
				currentVS.isMain = true;
				currentVS.openTime = openTime + (float)i * vsDelayIncrement;
				throwVector = Globals.GetRotatedCircleVector(vsIndexCount - 1, i, inputVector);
				currentVS.targetPosition = Globals.GetLinecastVector(currentPosition, currentPosition + throwVector * 7f, ChaosCollisions.layerAllWallAndObst);
				currentVS.throwStartPos = attackPosition + throwVector * 0.5f;
				currentVS.spawnChaosPillar = i + 1 == vsIndexCount;
				currentVS.CreateExitVS();
				if (i == 0)
				{
					currentVS.followTrans = parent.transform;
				}
				else
				{
					currentVS.followTrans = vsArray[i - 1].exitVS.transform;
					currentVS.anim.Play("Hidden");
				}
				vsArray[i] = currentVS;
			}
		}

		private IEnumerator HandleCooldown()
		{
			while (DetonateAvailable)
			{
				yield return null;
			}
			StartCooldownTimer();
		}

		private void CleanUpVS(Vector3 givenPosition)
		{
			for (int i = 0; i < vsIndexCount; i++)
			{
				currentVS = vsArray[i];
				if (!(currentVS == null))
				{
					currentVS.transform.position = givenPosition;
					if (currentVS.exitVS != null)
					{
						currentVS.exitVS.transform.position = givenPosition;
					}
				}
			}
		}

		private void DetonateVS()
		{
			if (vsArray[0] == null || vsArray[0].detonateQueued)
			{
				return;
			}
			vsArray[0].Detonate();
			for (int i = 1; i < vsIndexMax; i++)
			{
				if (!(vsArray[i] == null))
				{
					vsArray[i].OpenStopwatchID = ChaosStopwatch.Begin((float)i * vsDelayIncrement);
					vsArray[i] = null;
				}
			}
		}
	}

