using System;
using UnityEngine;

public class VoidShift : ThrownItem
{
	private static GameObject prefab;

	[HideInInspector]
	public Attack attack;

	private Collider2D attackCollider;

	[HideInInspector]
	public Transform followTrans;

	public Vector3 throwStartPos;

	public bool isMain;

	[HideInInspector]
	public float openTime = 2f;

	private int openStopwatchID;

	[HideInInspector]
	public bool detonateQueued;

	[HideInInspector]
	public bool exitDetonateQueued;

	[HideInInspector]
	public int pillarHitCount = 10;

	[HideInInspector]
	public float pillarHitInterval = 0.1f;

	[HideInInspector]
	public VoidShift exitVS;

	private Vector2 exitPosition;

	private ParticleEffect blobChargeEffect;

	public Transform linkSpriteTrans;

	public SpriteRenderer linkSprite;

	public SpriteRenderer linkOriginSprite;

	private Transform mainTrans;

	public VoidShift mainVS;

	public bool landed;

	public bool spawnChaosPillar = true;

	private bool exitVSCreated;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/VoidShift.prefab"));

	public float RemainingTime => ChaosStopwatch.GetRemainingTime(openStopwatchID);

	public int OpenStopwatchID
	{
		set
		{
			openStopwatchID = value;
			if (exitVS != null)
			{
				exitVS.openStopwatchID = value;
			}
		}
	}

	public override void Awake()
	{
		base.Awake();
		attack = transform.Find("Attack").GetComponent<Attack>();
		attackCollider = attack.transform.GetComponent<Collider2D>();
	}

	public override void Start()
	{
		base.Start();
		if (isMain)
		{
			Attack attack = this.attack;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			Attack attack2 = this.attack;
			attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			if (!exitVSCreated)
			{
				CreateExitVS();
			}
			SoundManager.PlayWithDistAndSPR("ChaosBeamStart", transform.position);
		}
	}

	public void CreateExitVS()
	{
		if (isMain)
		{
			exitVSCreated = true;
			openStopwatchID = ChaosStopwatch.Begin(openTime);
			exitVS = Globals.ChaosInst<VoidShift>(Prefab, transform.parent, throwStartPos);
			exitVS.isMain = false;
			exitVS.anim.Play("MarkerThrow", -1, 0f);
			exitVS.attack.SetAttackInfo(attack.atkInfo);
			exitVS.attack.ChangeAttackInfoLevel(2);
			exitVS.openStopwatchID = openStopwatchID;
			exitVS.pillarHitCount = pillarHitCount;
			exitVS.baseFlightTime = baseFlightTime;
			exitVS.throwHeight = throwHeight;
			exitVS.ThrowToTargetVector(targetPosition);
			exitVS.mainTrans = transform;
			exitVS.spawnChaosPillar = spawnChaosPillar;
			exitVS.mainVS = this;
		}
	}

	public override void OnLanding()
	{
		base.OnLanding();
		landed = true;
		if (!detonateQueued && baseFlightTime > 0f && throwHeight > 0f)
		{
			if (Globals.CheckCircle(transform.position, 0.125f, ChaosCollisions.layerPit))
			{
				anim.Play("MarkerIdle", -1, 0f);
			}
			else
			{
				anim.Play("MarkerIdleAir", -1, 0f);
			}
			PoolManager.GetPoolItem<ParticleEffect>("ChaosLightningBurst").Emit(3, transform.position);
			string audioID = "ChaosLightningCrackle";
			Vector2? soundOrigin = transform.position;
			float standardPitchRange = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
			CameraController.ShakeCamera(0.4f);
			DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
			int particleCount = 20;
			standardPitchRange = 0.25f;
			Vector3? emitPosition = transform.position;
			poolItem.EmitCircle(particleCount, standardPitchRange, -1f, -1f, emitPosition);
			SoundManager.PlayAudioWithDistance("Thud", transform.position);
			linkSprite.enabled = true;
			mainVS.linkOriginSprite.enabled = true;
		}
	}

	public override void Update()
	{
		base.Update();
		if (!isMain && !detonateQueued)
		{
			if (PercentComplete >= 0.9f && PercentComplete < 1f)
			{
				anim.Play("MarkerIdle", -1, 0f);
			}
			else if (PercentComplete >= 1f)
			{
				Vector3 normalized = (mainTrans.position - transform.position).normalized;
				float num = Vector2.Distance(mainTrans.position, transform.position);
				linkSpriteTrans.localScale = new Vector3(0.125f, num, 1f);
				linkSpriteTrans.localEulerAngles = Globals.GetRotationVector(normalized);
				linkSpriteTrans.localPosition = normalized * num * 0.5f;
			}
		}
	}

	public override void FixedUpdate()
	{
		base.FixedUpdate();
		if (detonateQueued || !ChaosStopwatch.Check(openStopwatchID) || (exitVS != null && !exitVS.landed))
		{
			return;
		}
		detonateQueued = true;
		linkSprite.enabled = false;
		linkOriginSprite.enabled = false;
		followTrans = null;
		if (isMain)
		{
			anim.Play("Open", -1, 0f);
			return;
		}
		spriteRenderer.sortingLayerName = "Default";
		anim.Play("MarkerOpen", -1, 0f);
		string audioID = "EnemyDead";
		Vector2? soundOrigin = transform.position;
		float overridePitch = UnityEngine.Random.Range(1.1f, 1.2f);
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
		if (spawnChaosPillar)
		{
			CreateChaosPillar();
		}
	}

	private void LateUpdate()
	{
		if (followTrans != null)
		{
			transform.position = followTrans.position;
		}
	}

	private void OnTargetHit(Entity givenEnt)
	{
		if (!(exitVS == null) && !(givenEnt == null) && !givenEnt.health.ignoreGrab)
		{
			exitPosition = exitVS.transform.position;
			givenEnt.transform.position = exitPosition;
			if (givenEnt.rigidbody2D != null)
			{
				givenEnt.rigidbody2D.MovePosition(exitPosition);
			}
		}
	}

	private void CreateChaosPillar()
	{
		ChaosPillar chaosPillar = Globals.ChaosInst<ChaosPillar>(ChaosPillar.Prefab, transform.parent, transform.position);
		chaosPillar.attack.SetAttackInfo(attack.atkInfo);
		chaosPillar.finalAttackLevel = 2;
		chaosPillar.maxHitCount = pillarHitCount;
		chaosPillar.hitInterval = pillarHitInterval;
		chaosPillar.readyTime = 0.25f;
		chaosPillar.useCastCircle = false;
		chaosPillar.playSFXOnInterval = true;
	}

	public void FlipAttackCollider()
	{
		if (isMain)
		{
			if (attackCollider != null)
			{
				attackCollider.enabled = !attackCollider.enabled;
			}
			if (blobChargeEffect != null)
			{
				blobChargeEffect.Stop();
				blobChargeEffect = null;
			}
		}
	}

	public void Detonate()
	{
		ChaosStopwatch.Stop(openStopwatchID);
		if (isMain && exitVS != null)
		{
			exitVS.Detonate();
		}
	}
}

using UnityEngine;

public class ChaosCluster : ThrownItem
{
	private static GameObject prefab;

	private ChaosCluster currentCC;

	private Vector2 currentPosition;

	private Vector2 seedVector;

	private int clusterCount = 6;

	private ChaosQuickStopwatch lifeStopwatch = new ChaosQuickStopwatch(4f);

	private ChaosQuickStopwatch floatStopwatch = new ChaosQuickStopwatch(0.125f);

	private Vector3 floatPosition;

	private Vector3 floatOffsetPos;

	public bool isPrimer = true;

	private bool floatStarted;

	private bool floatCompleted;

	private string skillCategory = string.Empty;

	private string skillID = string.Empty;

	private int skillLevel;

	private bool skillIsUltimate;

	private ChaosPillar currentCP;

	public int cascadeCount;

	public int pillarHitCount = 8;

	public float pillarInterval = 0.1f;

	public int pillarFinalLevel = 2;

	public bool skipStartParticles;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/ThrownItems/ChaosCluster.prefab"));

	public override void Start()
	{
		base.Start();
		lifeStopwatch.IsRunning = true;
		currentPosition = transform.position;
		if (isPrimer)
		{
			ChaosBurst.Spawn(currentPosition, 5);
			if (!skipStartParticles)
			{
				PoolManager.GetPoolItem<ParticleEffect>("ChaosLightningBurst").Emit(3, currentPosition);
			}
			SoundManager.PlayWithDistAndSPR("ChaosBeamStart", currentPosition);
		}
	}

	public override void FixedUpdate()
	{
		if (!lifeStopwatch.IsRunning && gameObject != null)
		{
			Object.Destroy(gameObject);
		}
		if (!floatStarted || floatCompleted)
		{
			base.FixedUpdate();
		}
		if (!isPrimer)
		{
			return;
		}
		if (!floatStarted && isFalling)
		{
			floatStarted = true;
			floatStopwatch.IsRunning = true;
			floatPosition = spriteTrans.localPosition;
			floatOffsetPos = floatPosition + Vector3.up;
		}
		if (floatStarted && !floatCompleted)
		{
			if (floatStopwatch.IsRunning)
			{
				spriteTrans.localPosition = Vector3.Lerp(floatPosition, floatOffsetPos, floatStopwatch.TimePercentage);
				return;
			}
			floatCompleted = true;
			spriteStartPosition = spriteRenderer.transform.localPosition;
			landedHeight = 0.4f;
			baseFlightTime = 0.1f;
			throwHeight = throwHeight * 0.5f + 0.5f;
			ThrowToTargetVector(transform.position);
			PoolManager.GetPoolItem<DashAirBurst>().Burst(transform.position + Vector3.up * 3f, Vector2.up, useOffset: false);
			PoolManager.GetPoolItem<ParticleEffect>("AirWaveShockwave").Emit(1, transform.position + Vector3.up * 3f, localEulerAngles: Globals.GetRotationVector(Vector3.up), overrides: ParticleEffectOverrides.StartColorAlpha0p25);
			SoundManager.PlayWithDistAndSPR("ChaosBall", transform.position);
		}
	}

	public override void OnLanding()
	{
		base.OnLanding();
		currentPosition = transform.position;
		if (isPrimer)
		{
			cascadeCount--;
			if (skillIsUltimate)
			{
				CreateChaosPillar(currentPosition);
				if (cascadeCount > 0)
				{
					CreateSecondaryCluster(currentPosition, currentPosition, isCenter: true);
				}
			}
			else
			{
				CreateSecondaryCluster(currentPosition, currentPosition);
			}
			seedVector = Random.insideUnitCircle.normalized;
			for (int i = 0; i < clusterCount; i++)
			{
				CreateSecondaryCluster(currentPosition, currentPosition + Globals.GetRotatedCircleVector(clusterCount, i, seedVector) * Random.Range(2.75f, 5.5f));
			}
			PoolManager.GetPoolItem<ParticleEffect>("ChaosLightningBurst").Emit(5, currentPosition);
			DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
			int particleCount = 50;
			float scale = 0.33f;
			Vector3? emitPosition = currentPosition;
			poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
			CameraController.ShakeCamera(0.4f);
			SoundManager.PlayAudioWithDistance("ChaosLightningCrackle", currentPosition);
			string audioID = "ChaosBeamStart";
			Vector2? soundOrigin = currentPosition;
			scale = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, scale);
			ChaosBurst.Spawn(currentPosition, 50);
			lifeStopwatch.IsRunning = false;
		}
		else
		{
			CreateChaosPillar(currentPosition);
			ChaosBurst.Spawn(currentPosition, 5);
		}
	}

	public void SetSkillInfo(string givenCategory, string givenID, int givenLevel, bool givenUlt)
	{
		skillCategory = givenCategory;
		skillID = givenID;
		skillLevel = givenLevel;
		skillIsUltimate = givenUlt;
	}

	private void CreateSecondaryCluster(Vector2 givenPosition, Vector2 givenLocation, bool isCenter = false)
	{
		currentCC = Globals.ChaosInst<ChaosCluster>(Prefab, transform.parent, givenPosition);
		currentCC.SetSkillInfo(skillCategory, skillID, skillLevel, skillIsUltimate);
		if (isCenter)
		{
			currentCC.cascadeCount = cascadeCount;
			currentCC.isPrimer = cascadeCount > 0;
			currentCC.baseFlightTime = 0.75f;
			currentCC.throwHeight = 5f;
		}
		else
		{
			currentCC.spriteTrans.localScale = Vector3.one * 0.625f;
			currentCC.isPrimer = false;
			currentCC.baseFlightTime = 0.35f;
			currentCC.throwHeight = 3f;
		}
		currentCC.ThrowToTargetVector(givenLocation);
	}

	private void CreateChaosPillar(Vector2 givenPosition)
	{
		currentCP = Globals.ChaosInst<ChaosPillar>(ChaosPillar.Prefab, transform.parent, givenPosition);
		currentCP.attack.SetAttackInfo(skillCategory, skillID, skillLevel, skillIsUltimate);
		currentCP.finalAttackLevel = pillarFinalLevel;
		currentCP.useCastCircle = false;
		currentCP.readyTime = 0.0625f;
		currentCP.hitInterval = pillarInterval;
		currentCP.maxHitCount = pillarHitCount;
		currentCP.useChargeEffect = false;
		currentCP.playSFXOnInterval = true;
	}
}
