			{
				Attack attack = currentCB.attack;
				attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnBeamHit));
			}
		}
	}

	public void StopBeam()
	{
		beamCreated = true;
	}
