using System;
using UnityEngine;

public class ChaosBeam : Beam
{
	private static GameObject prefab;

	[HideInInspector]
	public float attackDuration = 10f;

	[HideInInspector]
	public int maxHitCount = 15;

	[HideInInspector]
	public bool targetHit;

	[HideInInspector]
	public int finalAttackLevel = 1;

	private ChaosQuickStopwatch expandStopwatch = new ChaosQuickStopwatch(0.15f);

	private float expandedWidth = 1f;

	private float baseWidth = 0.125f;

	private bool expandInProgress;

	private ParticleEffect afterEffectEmitter;

	private ParticleSystem lightningEmitter;

	private static AudioSource beamAudio;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/ChaosBeam.prefab"));

	public override void Awake()
	{
		base.Awake();
		afterEffectEmitter = transform.Find("AfterEffectEmitter").GetComponent<ParticleEffect>();
		lightningEmitter = transform.Find("ChaosEmitter").GetComponent<ParticleSystem>();
	}

	public override void Start()
	{
		hitStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, hitInterval, Mathf.CeilToInt(attackDuration / hitInterval));
		Attack attack = base.attack;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		Attack attack2 = base.attack;
		attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		base.Start();
		expandedWidth = beamThickness;
		beamThickness = baseWidth;
		expandStopwatch.IsRunning = true;
		expandInProgress = true;
		CameraController.ShakeCamera();
		SoundManager.PlayAudioWithDistance("ChaosBeamStart", transform.position);
	}

	public override void Update()
	{
		base.Update();
		if (beamActive)
		{
			HandleAudio();
		}
	}

	public override void FixedUpdate()
	{
		if (expandInProgress)
		{
			beamThickness = Mathf.Lerp(baseWidth, expandedWidth, expandStopwatch.TimePercentage);
			expandInProgress = expandStopwatch.IsRunning;
		}
		float y = Vector2.Distance(transform.position, beamTipTrans.position);
		Vector3 vector = (transform.position + beamTipTrans.position) * 0.5f;
		vector = (transform.position + beamTipTrans.position) * 0.5f;
		lightningEmitter.transform.position = vector;
		ParticleSystem.ShapeModule shape = lightningEmitter.shape;
		shape.box = new Vector3(beamThickness * 0.65f, y, 1f);
		base.FixedUpdate();
	}

	private void OnDestroy()
	{
		HandleAudio(status: false);
	}

	public override void PlayOnReadyEffect()
	{
		int remainingIntervals = ChaosStopwatch.GetRemainingIntervals(hitStopwatchID);
		if (remainingIntervals == 1)
		{
			expandInProgress = false;
			beamThickness = expandedWidth * 1.25f;
			if (targetHit)
			{
				attack.ChangeAttackInfoLevel(finalAttackLevel);
			}
		}
	}

	private void OnTargetHit(Entity givenEnt)
	{
		if (!targetHit && !(givenEnt == null) && !(givenEnt is Destructible))
		{
			targetHit = true;
			hitStopwatchID = ChaosStopwatch.Begin(hitInterval, useInterval: true, hitInterval, maxHitCount);
			Attack attack = base.attack;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		}
	}

	public void Hide()
	{
		beamActive = false;
		currentMaxRange = 0f;
		attackCollider.enabled = false;
		beamThickness = 0f;
		beamSprite.enabled = false;
		beamTipTrans.gameObject.SetActive(value: false);
		beamStartObj.SetActive(value: false);
	}

	public override void StopBeam()
	{
		float num = Vector2.Distance(transform.position, beamTipTrans.position);
		Vector3 value = (transform.position + beamTipTrans.position) * 0.5f;
		ParticleSystem.ShapeModule shape = afterEffectEmitter.effectEmitter.shape;
		shape.box = new Vector3(beamThickness * 0.66f, num, 1f);
		afterEffectEmitter.Emit((int)(2.5 * (double)num), value);
		lightningEmitter.Stop();
		Hide();
		UnityEngine.Object.Destroy(gameObject, 1.5f);
		HandleAudio(status: false);
	}

	private void HandleAudio(bool status = true)
	{
		if (status)
		{
			if (beamAudio == null || !beamAudio.isPlaying)
			{
				beamAudio = SoundManager.PlayAudioWithDistance("ChaosBeamLoop", transform.position);
			}
		}
		else if (beamAudio != null)
		{
			beamAudio.Stop();
			beamAudio = null;
		}
	}
}

