		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		Attack attack2 = attackBox;
		attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		SoundManager.PlayWithDistAndSPR("ChaosBeamStart", transform.position);
		if (useAltStart)
		{
			moveStopwatch.SetDelay(0.2f);
			transform.localScale *= 1.25f;
		}
		originalMoveSpeed = moveSpeed;
		moveSpeed = 0f;
		moveStopwatch.IsRunning = true;
	}

	public override void Update()
	{
		if (!resetQueued && !targetHit)
		{
			base.Update();
		}
	}

	public override void FixedUpdate()
	{
		if (resetQueued)
		{
			return;
		}
		if (ChaosStopwatch.Check(effectStopwatchID))
		{
			PlayEffects();
		}
		if (targetHit)
		{
			chaosEffect.Stop();
			if (chargeEffect != null)
			{
				chargeEffect.Stop();
				chargeEffect.effectEmitter.Clear();
			}
			if (hitEntity == null || hitEntity.currentStateName.Contains("Dead"))
			{
				ChaosStopwatch.Stop(hitStopwatchID);
			}
			switch (ChaosStopwatch.CheckInterval(hitStopwatchID))
			{
			case StopwatchState.Ready:
				hitEntity.health.TakeDamage(hitAtkInfo);
				break;
			case StopwatchState.Done:
				hitComplete = true;
				ResetProjectile();
