			return;
		}
		base.FixedUpdate();
		if (!moveSpeedReset)
		{
			moveLerpValue = moveStopwatch.TimePercentage;
			moveSpeedReset = moveLerpValue >= 1f;
			moveSpeed = Mathf.Lerp(0f, originalMoveSpeed, Globals.GetSmoothLerpValue(moveLerpValue));
			if (moveLerpValue >= 0.75f && !chargeEffectStarted)
			{
				chargeEffectStarted = true;
				chargeEffect = PoolManager.GetPoolItem<ParticleEffect>("ChaosChargeEffect");
				chargeEffect.followTransform = transform;
				chargeEffect.reqFollowTrans = true;
				chargeEffect.Play(4f, transform.position);
			}
		}
	}

	private void LateUpdate()
	{
		if (resetQueued || !targetHit)
		{
			return;
		}
		if (eraseMode)
		{
			lerpValue = lerpStopwatch.TimePercentage;
			if (hitEntity != null)
			{
				hitEntity.transform.position = Vector3.Lerp(hitPosition, transform.position, lerpValue);
				hitEntity.transform.localScale = Vector3.Lerp(hitEntity.transform.localScale, Vector3.one * 0.01f, lerpValue);
			}
		}
		else if (followTrans != null)
		{
			lerpValue = lerpStopwatch.TimePercentage;
			followOffset = Vector3.Lerp(followOffset, Vector3.zero, lerpValue);
			transform.position = followTrans.position + followOffset;
		}
	}

	public override void ResetProjectile()
	{
		if (!targetHit || hitComplete)
		{
			resetQueued = true;
			moveVector = Vector2.zero;
			rigidbody2D.velocity = Vector2.zero;
			anim.Play("Close", -1, 0f);
			if (chargeEffect != null)
			{
				chargeEffect.effectEmitter.Stop();
			}
			chaosEffect.Stop();
			UnityEngine.Object.Destroy(gameObject, 1f);
			Attack attack = attackBox;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		}
	}

	private void OnTargetHit(Entity givenEntity)
	{
		if (!targetHit && !(givenEntity == null) && !(givenEntity == ignoreEntity) && !(givenEntity is Destructible) && !resetQueued)
		{
			targetHit = true;
			hitEntity = givenEntity;
			hitPosition = hitEntity.transform.position;
			eraseMode = hitEntity is Enemy && !(hitEntity is MiniBoss) && !(hitEntity is Boss) && !(hitEntity is TrainingDummy) && !(hitEntity is Pinata);
			if (eraseMode)
			{
				hitCount = 999;
				NullifyEnemy(hitEntity as Enemy);
			}
			else
			{
				attackBox.atkInfo.odProgMultiplier = 0.5f;
			}
			hitAtkInfo = attackBox.GetAtkInfoAtLevel(2);
			hitAtkInfo.isDamageOverride = useDmgOverride;
			attackBox.gameObject.SetActive(value: false);
			wallCollider.enabled = false;
			hitStopwatchID = ChaosStopwatch.Begin(hitInterval, useInterval: true, hitInterval, hitCount);
			CreateContinuation();
			moveVector = Vector2.zero;
			rigidbody2D.velocity = Vector2.zero;
			anim.Play("Open", -1, 0f);
			followTrans = hitEntity.hurtBoxTransform;
			followOffset = transform.position - followTrans.position;
			hitTrans = followTrans;
			lerpStopwatch.IsRunning = true;
			Attack attack = attackBox;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		}
	}

	private void NullifyEnemy(Enemy givenEnemy)
	{
		if (!(givenEnemy == null))
		{
			givenEnemy.myOrigin = transform.position;
			if (!givenEnemy.fsm.currentStateName.Contains("Dead"))
			{
				givenEnemy.fsm.ChangeState(givenEnemy.fsm.defaultStateName);
			}
			givenEnemy.alertRadius = 0f;
			givenEnemy.alertNearbyEnemiesRadius = 0f;
			givenEnemy.maxAlertDistance = 0f;
			givenEnemy.escapeRadius = 0f;
			givenEnemy.attackRadius = 0f;
			givenEnemy.surroundRadius = 0f;
			HandleEdgeCases(givenEnemy);
		}
	}

	private void HandleEdgeCases(Enemy givenEnemy)
	{
		if (givenEnemy is Blob)
		{
			((Blob)givenEnemy).divide = false;
		}
	}

	public void PlayEffects(int givenValue = 0)
	{
		effectStopwatchID = ChaosStopwatch.Begin(EffectDelay);
		PoolManager.GetPoolItem<ParticleEffect>("ChaosLightningBurst").Emit(2, transform.position);
