	{
		ChaosEraser chaosEraser = (ChaosEraser)Projectile.CreateProjectile(parentEntity, Prefab, (Vector2)transform.position + moveVector * 0.75f);
		chaosEraser.moveVector = moveVector;
		chaosEraser.attackBox.SetAttackInfo(hitAtkInfo.skillCategory, hitAtkInfo.skillID);
		chaosEraser.attackBox.knockbackOverwriteVector = moveVector;
