		lowerChargeTimeOnEmpower = false;
		audioStopwatch = new ChaosQuickStopwatch(0.2f);
		delayStopwatch = new ChaosQuickStopwatch(0.5f);
		chargedStopwatch = new ChaosQuickStopwatch(0.75f);
	}

	public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
	{
	}

	public override void OnEnter()
	{
		useCastBar = !isUltimate;
		ultFired = !isUltimate;
		base.OnEnter();
		chargedStarted = false;
		delayStarted = false;
		delayCompleted = false;
		if (isUltimate)
		{
			fullyCharged = true;
		}
	}

	public override void ExecuteSkill()
	{
		if (!ultFired)
		{
			ultFired = true;
			parent.anim.PlayDirectional(parent.ForehandAnimStr, -1, animExecTime);
			FireMainProj(isPrimary: true);
			CreateHoldProjectile();
			ultStopwatchID = ChaosStopwatch.Begin(0.25f);
		}
		else if (ChaosStopwatch.Check(ultStopwatchID))
		{
			base.ExecuteSkill();
			FireMainProj();
			parent.anim.PlayDirectional(parent.BackhandAnimStr, -1, animExecTime);
		}
	}

	public override Projectile CreateHoldProjectile()
	{
		currentCB = (ChaosBall)base.CreateHoldProjectile();
		currentCB.subProjCount = ((!isUltimate || ultFired) ? 5 : maxSubProjCount);
		currentCB.orbitRadius = 1.75f;
		currentCB.orbitSpeed = 2.5f;
		currentCB.EnableColliders(status: false);
		currentCB.mainScale = 1f;
		return currentCB;
	}

	public override void AddProjectileCharge()
	{
		if (currentCB != null && currentCB.subProjCount < maxSubProjCount)
		{
			currentCB.AddSubProjectile(3);
		}
	}

	public override void PlayChargeEffects()
	{
		if (fullyCharged)
		{
			if (!isUltimate)
			{
				if (!delayCompleted)
				{
					if (!delayStarted)
					{
						delayStarted = true;
						delayStopwatch.IsRunning = true;
					}
					if (!delayStopwatch.IsRunning)
					{
						delayCompleted = true;
						parent.hud.castBar.ForceQuitCasting();
					}
				}
				else if (!chargedStarted)
				{
					chargedStarted = true;
					chargedStopwatch.IsRunning = true;
					parent.hud.castBar.StartCast(chargedStopwatch.ID, givenStatus: false);
				}
				else if (!chargedStopwatch.IsRunning)
				{
					holdReleased = true;
				}
			}
			FireSubProj(Globals.GetCirclePositionVector(12, UnityEngine.Random.Range(0, 4)));
			FireSubProj(Globals.GetCirclePositionVector(12, UnityEngine.Random.Range(4, 8)));
			FireSubProj(Globals.GetCirclePositionVector(12, UnityEngine.Random.Range(8, 12)));
		}
		if (!audioStopwatch.IsRunning)
		{
			audioStopwatch.IsRunning = true;
			SoundManager.PlayWithDistAndSPR("ChaosWarp", parent.attackOriginTrans.position);
		}
	}

	private void FireMainProj(bool isPrimary = false)
	{
		if (currentCB != null)
		{
			currentCB.moveSpeed = 20f;
			currentCB.maxHomingDelay = (float)currentCB.subProjCount * 0.05f;
			currentCB.EnableColliders();
			currentCB.SetSubProjOrbitVars(16f, 1f);
			if (isUltimate || currentCB.subProjCount >= maxSubProjCount)
			{
				currentCB.spawnChaosPillar = true;
			}
			if (isPrimary)
			{
				Projectile projectile = currentProjectile;
				Vector2 moveVector = inputVector;
				string audioString = fireAudioID;
				FireProjectile(projectile, moveVector, setKnockbackVector: true, 0f, 0f, audioString);
			}
		}
		parent.movement.moveVector = -inputVector;
		parent.movement.MoveToMoveVector(10f);
		SoundManager.PlayWithDistAndSPR("ChaosFormLong", parent.transform.position);
	}

	private void FireSubProj(Vector2 givenVector)
	{
		subCB = (ChaosBall)CreateProjectile(ChaosBall.Prefab, null, null, null, setAtkInfo: false);
		subCB.attackBox.SetAttackInfo(parent.skillCategory, skillID, 4, isUltimate);
		subCB.isMain = false;
		subCB.flyTime = 0.5f;
		subCB.moveVector = givenVector;
		subCB.transform.position = HoldPosition + givenVector * 0.75f;
		subCB.pointTowardMoveVector = true;
		subCB.moveSpeed = 20f;
		subCB.attackBox.knockbackOverwriteVector = givenVector;
		subCB.anim.Play("Needle", -1, 0f);
		subCB.isNeedle = true;
	}
}

public class ProjectileChargeAttackState(string newName, FSM newFSM, Player newPlayer) : ProjectileHoldAttackState(newName, newFSM, newPlayer)
{
	public bool useCastBar = true;

	public int maxCharge = 10;

	public int minCharge = 5;

	public float chargeTime = 0.2f;

	public float calcChargeTime;

	public int chargeStopwatchID;

	public bool fullyCharged;

	public int postStopwatchID;

	public AudioSource chargeAudioSource;

	public string chargeAudioID = string.Empty;

	public bool ignoreAudioIsPlaying;

	public bool lowerChargeTimeOnEmpower = true;

	public override void OnEnter()
	{
		base.OnEnter();
		calcChargeTime = ((!lowerChargeTimeOnEmpower || !IsEmpowered) ? chargeTime : (chargeTime * 0.5f));
		fullyCharged = maxCharge - minCharge <= 0;
		if (useCastBar && !fullyCharged)
		{
			parent.hud.castBar.StartCast(ChaosStopwatch.Begin(calcChargeTime * (float)(maxCharge - minCharge)), givenStatus: true);
		}
		PlayChargeEffects();
	}

	public override void HandleHoldButton()
	{
		base.HandleHoldButton();
		if (!fullyCharged)
		{
			switch (ChaosStopwatch.CheckInterval(chargeStopwatchID))
			{
			case StopwatchState.Ready:
				PlayChargeEffects();
				AddProjectileCharge();
				break;
			case StopwatchState.Done:
				fullyCharged = true;
				postStopwatchID = ChaosStopwatch.Begin(calcChargeTime);
				break;
			}
		}
		else
		{
			HandlePostStopwatch();
		}
	}

	public override void ExecuteSkill()
	{
		base.ExecuteSkill();
		if (useCastBar)
		{
			parent.hud.castBar.EndCast();
		}
		StopChargeAudio();
	}

	public override void OnExit()
	{
		base.OnExit();
		if (useCastBar)
		{
			parent.hud.castBar.EndCast();
		}
		StopChargeAudio();
	}

	public override Projectile CreateHoldProjectile()
	{
		chargeStopwatchID = ChaosStopwatch.Begin(calcChargeTime, useInterval: true, calcChargeTime, maxCharge - minCharge);
		return base.CreateHoldProjectile();
	}

	public virtual void HandlePostStopwatch()
	{
		if (ChaosStopwatch.Check(postStopwatchID))
		{
			postStopwatchID = ChaosStopwatch.Begin(calcChargeTime);
			PlayChargeEffects();
		}
	}

	public virtual void PlayChargeEffects()
	{
		if (!(chargeAudioID == string.Empty))
		{
			if (ignoreAudioIsPlaying)
			{
				StopChargeAudio();
			}
			if (currentProjectile != null)
			{
				chargeAudioSource = SoundManager.PlayIfNotPlaying(chargeAudioID, chargeAudioSource, currentProjectile.transform);
			}
		}
	}

	public void StopChargeAudio()
	{
		if (chargeAudioSource != null)
		{
			chargeAudioSource.Stop();
		}
	}

	public virtual void AddProjectileCharge()
	{
	}
}

public class ProjectileHoldAttackState : ProjectileAttackState
{
	public GameObject projectilePrefab;

	public Projectile currentProjectile;

	public float holdRange = 1f;

	public string fireAudioID = string.Empty;

	public bool updateRotation;

	public bool recenterOnRelease = true;

	public override string OnEnterAnimStr => parent.ChargeAnimStr;

	public override string OnHoldAnimStr => parent.ChargeAnimStr;

	public virtual Vector2 HoldPosition => (Vector2)parent.attackOriginTrans.position - Entity.GetFacingDirectionVector(parent.facingDirection) * holdRange;

	public ProjectileHoldAttackState(string newName, FSM newFSM, Player newPlayer)
		: base(newName, newFSM, newPlayer)
	{
		disableStartCooldown = true;
		isHoldSkill = true;
	}

	public override void OnEnter()
	{
		base.OnEnter();
		CreateHoldProjectile();
	}

	public override void Update()
	{
		if (currentProjectile == null)
		{
			ExitToSkillOrRunOrIdle();
		}
		else
		{
			base.Update();
		}
	}

	public override void HandleHoldButton()
	{
		base.HandleHoldButton();
		if (!(currentProjectile == null))
		{
			currentProjectile.RefreshFlightTime();
			currentProjectile.transform.position = HoldPosition;
			if (updateRotation)
			{
				currentProjectile.transform.localEulerAngles = Globals.GetRotationVector(inputVector);
			}
		}
	}

	public override void ExecuteSkill()
	{
		base.ExecuteSkill();
		StartCooldownTimer();
		parent.anim.PlayDirectional(parent.ForehandAnimStr, -1, animExecTime);
		if (!(currentProjectile == null))
		{
			if (updateRotation)
			{
				currentProjectile.isPointedAtMoveVector = false;
			}
			if (recenterOnRelease)
			{
				currentProjectile.transform.position = parent.attackOriginTrans.position;
			}
			Projectile projectile = currentProjectile;
			Vector2 moveVector = inputVector;
			string audioString = fireAudioID;
			FireProjectile(projectile, moveVector, setKnockbackVector: true, 0f, 0f, audioString);
		}
	}

	public override void OnExit()
	{
		if (!skillExecuted && currentProjectile != null)
		{
			currentProjectile.ResetProjectile();
			StartCooldownTimer();
		}
		base.OnExit();
	}

	public virtual Projectile CreateHoldProjectile()
	{
		return currentProjectile = CreateProjectile(projectilePrefab, HoldPosition, (!updateRotation) ? Quaternion.identity : Globals.GetRotationQuaternion(inputVector));
	}
}

