	public ShockTouchBasic(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		isBasic = true;
		isMeleeSkill = true;
		attackPrefab = ShockTouchObject.Prefab;
		destroyAttackObjectOnExit = false;
		setParent = false;
		maxComboCount = 4;
		animStartTime = 0.25f;
		animExecTime = 0.3f;
		baseCancelThreshold = 0.4f;
		finalCancelThreshold = 0.6f;
		baseRunThreshold = 0.8f;
		finalRunThreshold = 0.9f;
		baseExitThreshold = 1f;

using System;
using System.Collections.Generic;
using Chaos.VectorExtensions;
using UnityEngine;

public class ChaosBall : Projectile
{
	private static GameObject prefab;

	private ChaosQuickStopwatch lightningEffectTimer;

	private float lightningEffectTime = 0.15f;

	public float mainScale = 2f;

	protected Movement movement;

	private CircleCollider2D[] circColliders;

	[HideInInspector]
	public bool isMain = true;

	[HideInInspector]
	public bool isNeedle;

	[HideInInspector]
	public bool isSubBall;

	protected Transform mainTrans;

	private ChaosBall subCB;

	private List<ChaosBall> subProjList;

	public int subProjCount = 5;

	protected ChaosQuickStopwatch lerpStopwatch;

	protected float lerpValue;

	protected bool converge;

	private Entity targetEntity;

	private bool targetHit;

	private Transform targetTrans;

	private bool isHoming;

	private bool homingStarted;

	private float homingBias = 25f;

	private int homingStopwatchID;

	[HideInInspector]
	public float maxHomingDelay = 0.5f;

	public bool isUltimate;

	[HideInInspector]
	public float orbitRadius = 1.25f;

	[HideInInspector]
	public float orbitSpeed = 12f;

	public bool useArc;

	public bool posArc = true;

	private ChaosQuickStopwatch arcStopwatch;

	private Vector2 initMoveVector;

	private Vector2 lerpExtVector;

	private float rotationalAngle;

	private Vector2 rightBound;

	private Vector2 leftBound;

	private float arcRange = 8f;

	private float accuracyOffset = 1f;

	[HideInInspector]
	public bool spawnChaosPillar;

	private AttackInfo subCBAtkInfo;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/ChaosBall.prefab"));

	public override void Awake()
	{
		base.Awake();
		movement = GetComponent<Movement>();
		circColliders = GetComponentsInChildren<CircleCollider2D>();
		lightningEffectTimer = new ChaosQuickStopwatch(lightningEffectTime);
	}

	public override void Start()
	{
		base.Start();
		if (!isMain)
		{
			return;
		}
		disableOnHit = false;
		transform.localScale *= mainScale;
		Attack attack = attackBox;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		Attack attack2 = attackBox;
		attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		attackBox.transform.localScale *= 3f;
		if (isUltimate)
		{
			transform.localScale *= 1.5f;
			orbitRadius = 2f;
			if (useArc)
			{
				initMoveVector = moveVector;
				moveSpeed = Mathf.Max(1f, moveSpeed);
				arcStopwatch = new ChaosQuickStopwatch(arcRange / moveSpeed);
				rotationalAngle = Vector3.Angle(Vector3.up, initMoveVector) * ((float)Math.PI / 180f) * ((!(initMoveVector.x > 0f)) ? 1f : (-1f));
				rightBound = new Vector2(Mathf.Cos(rotationalAngle), Mathf.Sin(rotationalAngle));
				rotationalAngle += (float)Math.PI;
				leftBound = new Vector2(Mathf.Cos(rotationalAngle), Mathf.Sin(rotationalAngle));
			}
		}
		subCBAtkInfo = attackBox.GetAtkInfoAtLevel(2);
		subProjList = new List<ChaosBall>();
		Vector2 normalized = UnityEngine.Random.insideUnitCircle.normalized;
		for (int i = 0; i < subProjCount; i++)
		{
			subProjList.Add(CreateSubChaosBall(Globals.GetRotatedCircleVector(subProjCount, i, normalized)));
		}
		SoundManager.PlayAudioWithDistance("ChaosFormLong", transform.position);
		SoundManager.PlayAudioWithDistance("ChaosBall", transform.position);
	}

	public override void UpdateCalculatedDamage(bool initDamageOverride = false)
	{
		base.UpdateCalculatedDamage(initDamageOverride);
		calculatedDamage += subProjCount * 5;
	}

	public override void Update()
	{
		if (isMain)
		{
			base.Update();
			if (!isSubBall && !isNeedle && !lightningEffectTimer.IsRunning)
			{
				PoolManager.GetPoolItem<ParticleEffect>("ChaosLightningBurst").Emit(2, transform.position, ParticleEffectOverrides.LayerTrail);
				lightningEffectTimer.IsRunning = true;
			}
		}
		else if (isHoming)
		{
			if (!homingStarted)
			{
				if (ChaosStopwatch.Check(homingStopwatchID))
				{
					homingStarted = true;
					moveSpeed *= 8f;
					flyTime = 0.75f;
					EnableColliders();
					RefreshFlightTime();
					SoundManager.PlayAudioWithDistance("ChaosBall", transform.position, null, 24f, -1f, 0.75f);
				}
			}
			else if (targetTrans == null || targetEntity == null || targetEntity.fsm.currentStateName.Contains("Dead"))
			{
				isMain = true;
			}
			else
			{
				moveVector = (moveVector + homingBias * Time.deltaTime * (Vector2)(targetTrans.position - transform.position).normalized).normalized;
				base.Update();
			}
		}
		else if (mainTrans == null)
		{
			isMain = true;
		}
		else
		{
			lerpValue = lerpStopwatch.TimePercentage;
			movement.orbitRadius = Mathf.Lerp(1f, orbitRadius, (!converge) ? lerpValue : (1f - lerpValue));
			movement.OrbitTarget(mainTrans.position, useTransform: true);
			if (lerpValue >= 1f)
			{
				converge = !converge;
				lerpStopwatch.IsRunning = true;
			}
		}
	}

	public override void FixedUpdate()
	{
		if (!useArc)
		{
			base.FixedUpdate();
			return;
		}
		if (!arcStopwatch.IsRunning)
		{
			posArc = !posArc;
			arcStopwatch.IsRunning = true;
		}
		lerpExtVector = accuracyOffset * Vector2.Lerp(rightBound, leftBound, (!posArc) ? (1f - arcStopwatch.TimePercentage) : arcStopwatch.TimePercentage);
		moveVector = (initMoveVector + lerpExtVector).normalized;
		base.FixedUpdate();
		transform.localEulerAngles = Globals.GetRotationVector(moveVector);
		if (attackBox != null)
		{
			attackBox.knockbackOverwriteVector = moveVector;
		}
	}

	public override void RefreshFlightTime(bool flyTimeOnly = false)
	{
		base.RefreshFlightTime(flyTimeOnly);
		if (!isMain || subProjList == null)
		{
			return;
		}
		foreach (ChaosBall subProj in subProjList)
		{
			if (subProj != null)
			{
				subProj.RefreshFlightTime(flyTimeOnly);
			}
		}
	}

	public override void ResetProjectile()
	{
		base.ResetProjectile();
		ChaosBurst.Spawn(transform.position, 1);
		if (isMain)
		{
			if (!targetHit)
			{
				ResetSubProjList();
			}
			if (spawnChaosPillar)
			{
				CreateChaosPillar();
			}
		}
	}

	private void ResetSubProjList()
	{
		if (subProjList == null)
		{
			return;
		}
		foreach (ChaosBall subProj in subProjList)
		{
			if (subProj != null)
			{
				subProj.InitHoming(null, null, transform.position, moveVector, useTimer: false);
			}
		}
	}

	private void OnTargetHit(Entity givenEnt)
	{
		if (targetHit || givenEnt == null || givenEnt is Destructible)
		{
			return;
		}
		targetHit = true;
		targetEntity = givenEnt;
		targetTrans = targetEntity.hurtBoxTransform;
		foreach (ChaosBall subProj in subProjList)
		{
			if (subProj != null)
			{
				subProj.InitHoming(targetEntity, targetTrans, transform.position, moveVector);
			}
		}
		ResetProjectile();
	}

	public ChaosBall CreateSubChaosBall(Vector2 givenVector)
	{
		subCB = Globals.ChaosInst<ChaosBall>(prefab, transform.parent, transform.position);
		subCB.parentObject = parentObject;
		subCB.parentEntity = parentEntity;
		subCB.attackBox.SetAttackInfo(subCBAtkInfo);
		subCB.goThroughWalls = true;
		subCB.isMain = false;
		subCB.isSubBall = true;
		subCB.mainTrans = transform;
		subCB.movement.InitOrbitAngle(givenVector);
		subCB.movement.orbitSpeed = orbitSpeed;
		(subCB.lerpStopwatch = new ChaosQuickStopwatch(UnityEngine.Random.Range(0.35f, 1f))).IsRunning = true;
		subCB.orbitRadius = orbitRadius;
		subCB.EnableColliders(status: false);
		subCB.anim.Play("IdleSub", -1, 0f);
		return subCB;
	}

	public void EnableColliders(bool status = true)
	{
		CircleCollider2D[] array = circColliders;
		foreach (CircleCollider2D circleCollider2D in array)
		{
			circleCollider2D.enabled = status;
		}
	}

	public void InitHoming(Entity givenEntity, Transform givenTrans, Vector2 givenPosition, Vector2 givenVector, bool useTimer = true)
	{
		isHoming = true;
		if (useTimer)
		{
			homingStopwatchID = ChaosStopwatch.Begin(UnityEngine.Random.Range(0.125f, maxHomingDelay));
		}
		targetEntity = givenEntity;
		targetTrans = givenTrans;
		moveVector = ((givenPosition - givenVector * 1.5f).Randomize(1f, 1f) - (Vector2)transform.position).normalized;
		moveSpeed *= 0.25f;
		anim.Play("IdleSub", -1, 0f);
		RefreshFlightTime();
	}

	public void AddSubProjectile(int givenCount = 1)
	{
		subProjCount += givenCount;
		for (int i = 0; i < givenCount; i++)
		{
			subProjList.Add(CreateSubChaosBall(UnityEngine.Random.insideUnitCircle.normalized));
		}
		UpdateCalculatedDamage();
	}

	public void SetSubProjOrbitVars(float givenSpeed, float givenRadius)
	{
		foreach (ChaosBall subProj in subProjList)
		{
			if (subProj != null)
			{
				subProj.movement.orbitSpeed = givenSpeed;
				subProj.orbitRadius = givenRadius;
			}
		}
	}

	private void CreateChaosPillar()
	{
		ChaosPillar chaosPillar = Globals.ChaosInst<ChaosPillar>(ChaosPillar.Prefab, null, transform.position);
		chaosPillar.attack.SetAttackInfo(attackBox.atkInfo, 3);
		chaosPillar.finalAttackLevel = 1;
		chaosPillar.maxHitCount = 5;
		chaosPillar.hitInterval = 0.125f;
		chaosPillar.readyTime = 0f;
		chaosPillar.useCastCircle = false;
		chaosPillar.playSFXOnInterval = true;
	}
}

