	private bool swordsCompleted;

	private List<int> timeIDList = new List<int>();

	private Dictionary<int, Vector2> timePosDict = new Dictionary<int, Vector2>();

	public override string OnEnterAnimStr => parent.GSlamAnimStr;

	public UseChaosSwordStorm(FSM fsm, Player parentPlayer)
		: base(staticID, fsm, parentPlayer)
	{
		hasSignatureVariant = true;
		empoweredStat.SetInitialBaseValue(newBaseVal: true);
		SetAnimTimes(0f, 0.2f, 0f, 0.55f, 0.75f);
	}

	public override void SetEmpowered(bool gs, BoolVarStatMod gm)
	{
	}

	public override void OnEnter()
	{
		base.OnEnter();
		if (isUltimate)
		{
			initDelay = 0f;
			randDelay = 0.02f;
			randSwordCount = 100;
			waveDelay = 0f;
			waveSideCount = 3;
		}
		else
		{
			initDelay = 0.25f;
			randDelay = 0.04f;
			randSwordCount = 35;
			waveDelay = 0.03f;
			waveSideCount = 2;
		}
	}

	public override void ExecuteSkill()
	{
		base.ExecuteSkill();
		waveVec = inputVector * 1.125f;
		startPos = (Vector2)parent.transform.position + waveVec;
		perpVec = Globals.GetPerpendicular(inputVector);
		parent.StartCoroutine(SpawnSwords(isUltimate));
	}

	private IEnumerator SpawnSwords(bool isUlt)
	{
		SoundManager.PlayAudioWithDistance("ChaosOpen", startPos);
		waveStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, waveDelay, waveMaxCount);
		waveCounter = 0;
		waveCompleted = false;
		randStopwatchID = ChaosStopwatch.Begin(initDelay, useInterval: true, randDelay, randSwordCount);
		randCompleted = false;
		if (audioStopwatch == null)
		{
			audioStopwatch = new ChaosQuickStopwatch(0.1f);
		}
		timeIDList.Clear();
		timePosDict.Clear();
		swordsCompleted = false;
		while (!swordsCompleted)
		{
			if (!waveCompleted)
			{
				switch (ChaosStopwatch.CheckInterval(waveStopwatchID))
				{
				case StopwatchState.Ready:
				{
					for (int i = -waveSideCount; i <= waveSideCount; i++)
					{
						QueueSword(ChaosStopwatch.Begin(dropDelay), waveVec * waveCounter + perpVec * i);
					}
					waveCounter++;
					break;
				}
				case StopwatchState.Done:
					waveCompleted = true;
					break;
				}
			}
			if (!randCompleted)
			{
				switch (ChaosStopwatch.CheckInterval(randStopwatchID))
				{
				case StopwatchState.Ready:
					QueueSword(ChaosStopwatch.Begin(dropDelay), waveVec * UnityEngine.Random.Range(0, waveMaxCount) + perpVec * UnityEngine.Random.Range(-waveSideCount, waveSideCount));
					break;
				case StopwatchState.Done:
					randCompleted = true;
					break;
				}
			}
			if (!audioStopwatch.IsRunning)
			{
				audioStopwatch.IsRunning = true;
				SoundManager.PlayAudioWithDistance("ChaosPop", startPos);
			}
			for (int num = timeIDList.Count - 1; num >= 0; num--)
			{
				if (ChaosStopwatch.Check(timeIDList[num]))
				{
					PoolManager.GetPoolItem<AttackGeneric>().CircleAttack(timePosDict[timeIDList[num]], parent.skillCategory, skillID, currentLevel, isUlt, 1.25f);
					timeIDList.RemoveAt(num);
				}
			}
			swordsCompleted = randCompleted && waveCompleted && timeIDList.Count <= 0;
			yield return null;
		}
		SoundManager.PlayAudioWithDistance("ChaosClose", startPos);
	}

	private void QueueSword(int givenID, Vector2 givenPosition)
	{
		givenPosition += startPos;
		PoolManager.GetPoolItem<ParticleEffect>(emitterNames[UnityEngine.Random.Range(0, 3)]).Emit(1, givenPosition);
		timeIDList.Add(givenID);
		timePosDict.Add(givenID, givenPosition);
	}
}

public class UseChaosSwordSummon : ProjectileAttackState
{
	public new static string staticID = "UseChaosSwordSummon";

	private static WaitForSeconds waitForFlyTime = new WaitForSeconds(0.375f);

	private ChaosSwordProjectile[] swordArr = new ChaosSwordProjectile[7];

	private ChaosSwordProjectile currentCS;

	private Vector2 spawnPosition;

	private int spawnCount;

	public override string OnEnterAnimStr => parent.ForehandAnimStr;

	public UseChaosSwordSummon(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		hasSignatureVariant = true;
		empoweredStat.SetInitialBaseValue(newBaseVal: true);
