	}

	public override void SetEmpowered(bool gs, BoolVarStatMod gm)
	{
	}

	public override void ExecuteSkill()
	{
		base.ExecuteSkill();
		spawnPosition = parent.attackOriginTrans.position;
		spawnCount = ((!isUltimate) ? 1 : 3);
		ChaosBurst.Spawn(spawnPosition, spawnCount + 1);
		SoundManager.PlayWithDistAndSPR("ChaosWarble", spawnPosition, 1.1f);
		SoundManager.PlayWithDistAndSPR("QuickSwing", spawnPosition);
		CameraController.ShakeCamera(0.2f);
		for (int i = -spawnCount; i <= spawnCount; i++)
		{
			swordArr[i + spawnCount] = CreateChaosSword(spawnPosition, Globals.GetRotatedCircleVector(32, i, inputVector));
		}
		parent.StartCoroutine(HandleDetonation());
	}

	private ChaosSwordProjectile CreateChaosSword(Vector2 givenPosition, Vector2 givenVector)
	{
		currentCS = (ChaosSwordProjectile)CreateProjectile(ChaosSwordProjectile.Prefab, givenPosition + givenVector, Globals.GetRotationQuaternion(givenVector));
		currentCS.isUltimate = isUltimate;
		AttackInfo.SetHurtTargets(currentCS.attackBox.atkInfo.targetNames);
		FireProjectile(currentCS, givenVector, setKnockbackVector: true, 0f, 0f, string.Empty);
		return currentCS;
	}

	private IEnumerator HandleDetonation()
	{
		yield return waitForFlyTime;
		bool allowDetonate = false;
		for (int i = 0; i < swordArr.Length; i++)
		{
			if (swordArr[i] != null && swordArr[i].targetHit)
			{
				allowDetonate = true;
				break;
			}
		}
		if (!allowDetonate)
		{
			yield break;
		}
		string holdStr = "Skill" + skillSlot;
		int delayStopwatchID = ChaosStopwatch.Begin(1.75f);
		allowDetonate = false;
		parent.overheadPrompt.DisplayPrompt("Slot" + skillSlot, loop: true);
		while (!ChaosStopwatch.Check(delayStopwatchID))
		{
			if (parent.inputDevice.GetButton(holdStr))
			{
				allowDetonate = true;
				ChaosStopwatch.Stop(delayStopwatchID);
			}
			yield return null;
		}
		parent.overheadPrompt.HidePrompt(string.Empty);
		if (!allowDetonate)
		{
			yield break;
		}
		for (int j = 0; j < swordArr.Length; j++)
		{
			ChaosSwordProjectile tempCS = swordArr[j];
			swordArr[j] = null;
			if (tempCS != null && tempCS.targetHit)
			{
				tempCS.flyTime = 0.125f * (float)j;
				tempCS.RefreshFlightTime();
			}
		}
	}
}

