using System;
using UnityEngine;

public class ChaosSwordProjectile : Projectile
{
	private static GameObject prefab;

	public Transform ringTrans;

	public GameObject bladeObj;

	public bool isUltimate;

	public bool targetHit;

	private bool followTarget;

	private Entity hitEntity;

	private Transform hitTrans;

	private Vector2 detonateLocation;

	public float detonateDelay = 2f;

	private bool detonateCompleted;

	private bool resetQueued;

	private ChaosSwordSummon currentCS;

	public static GameObject Prefab
	{
		get
		{
			if (prefab == null)
			{
				prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/ChaosSwordProjectile.prefab");
			}
			return prefab;
		}
	}

	public override void Start()
	{
		base.Start();
		Attack attack = attackBox;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		Attack attack2 = attackBox;
		attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
	}

	public override void Update()
	{
		base.Update();
		if (followTarget && (hitEntity == null || hitEntity.currentStateName.Contains("Dead")))
		{
			Detonate();
		}
	}

	private void LateUpdate()
	{
		if (targetHit && followTarget && hitTrans != null)
		{
			transform.position = hitTrans.position;
		}
	}

	public override void HandleWallCollision(Collider2D other)
	{
		OnTargetHit(null);
		bladeObj.SetActive(value: false);
	}

	public override void ResetProjectile()
	{
		if (!resetQueued)
		{
			resetQueued = true;
			Attack attack = attackBox;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			if (targetHit)
			{
				Detonate();
			}
			updateVelocity = false;
			rigidbody2D.velocity = Vector2.zero;
			anim.Play("Close", -1, 0f);
			SoundManager.PlayAudioWithDistance("ChaosFade", transform.position);
			UnityEngine.Object.Destroy(gameObject, 0.25f);
		}
	}

	private void OnTargetHit(Entity givenEnt)
	{
		if (targetHit)
		{
			return;
		}
		targetHit = true;
		anim.Play("Primed", -1, UnityEngine.Random.value);
		updateVelocity = false;
		rigidbody2D.velocity = Vector2.zero;
		if (givenEnt is Destructible)
		{
			Detonate();
			return;
		}
		if (givenEnt != null)
		{
			followTarget = true;
			hitEntity = givenEnt;
			hitTrans = givenEnt.hurtBoxTransform;
			transform.position = hitTrans.position;
		}
		ringTrans.position = transform.position + Vector3.down;
		flyTime = detonateDelay + UnityEngine.Random.Range(-0.125f, 0.125f);
		RefreshFlightTime();
	}

	public void Detonate()
	{
		if (!detonateCompleted && targetHit)
		{
			detonateCompleted = true;
			detonateLocation = ringTrans.position;
			if (followTarget)
			{
				detonateLocation += UnityEngine.Random.insideUnitCircle * 0.75f;
			}
			followTarget = false;
			currentCS = Globals.ChaosInst<ChaosSwordSummon>(ChaosSwordSummon.Prefab, null, detonateLocation);
			currentCS.attack.SetAttackInfo(attackBox.GetAtkInfoAtLevel(2));
			currentCS.isUltimate = isUltimate;
			ResetProjectile();
		}
	}
}
using UnityEngine;

public class ChaosSwordSummon : MonoBehaviour
{
	private static GameObject _prefab;

	private static int audioStopwatchID;

	public Animator anim;

	public Attack attack;

	public Collider2D attackCol;

	public SpriteRenderer swordSprite;

	private Transform followTrans;

	private float delayTime;

	private int delayStopwatchID = -1;

	private bool delayCompleted;

	private int atkCount = 5;

	private int atkStopwatchID;

	private bool atkCompleted;

	private bool firstAttack = true;

	public bool isUltimate;

	public static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/ChaosSwordSummon.prefab");
			}
			return _prefab;
		}
	}

	private void Start()
	{
		if (delayTime > 0f)
		{
			delayStopwatchID = ChaosStopwatch.Begin(delayTime);
		}
		if (isUltimate)
		{
			atkCount = 10;
		}
		SoundManager.PlayWithDistAndSPR("ChaosBeamStart", transform.position, 0.85f);
	}

	private void FixedUpdate()
	{
		if (atkCompleted)
		{
			return;
		}
		if (!delayCompleted)
		{
			if (!ChaosStopwatch.Check(delayStopwatchID))
			{
				return;
			}
			InitAttack();
			CameraController.ShakeCamera(0.4f);
		}
		switch (ChaosStopwatch.CheckInterval(atkStopwatchID))
		{
		case StopwatchState.Running:
			attackCol.enabled = true;
			break;
		case StopwatchState.Ready:
			if (firstAttack)
			{
				attack.ChangeAttackInfoLevel((!isUltimate) ? 3 : 4);
			}
			attackCol.enabled = false;
			if (ChaosStopwatch.Check(audioStopwatchID))
			{
				audioStopwatchID = ChaosStopwatch.Begin(0.1f);
				SoundManager.PlayWithDistAndSPR("ChaosLightningCrackle", transform.position);
			}
			break;
		case StopwatchState.Done:
			atkCompleted = true;
			anim.Play("Fade", -1, 0f);
			SoundManager.PlayWithDistAndSPR("ChaosStormEnd", transform.position, 0.8f);
			if (gameObject != null)
			{
				Object.Destroy(gameObject, 0.5f);
			}
			break;
		}
	}

	private void LateUpdate()
	{
		if (!delayCompleted && followTrans != null)
		{
			transform.position = followTrans.position;
		}
	}

	public void SetTarget(Transform givenTrans)
	{
		if (!(givenTrans == null))
		{
			followTrans = givenTrans;
			delayTime = 5f;
		}
	}

	public void InitAttack()
	{
		if (!delayCompleted)
		{
			delayCompleted = true;
			anim.Play("Attack", -1, 0f);
			atkStopwatchID = ChaosStopwatch.Begin(0.125f, useInterval: true, 0.125f, atkCount);
		}
	}

	public void SetFlashAmount(float flashAmount)
	{
		swordSprite.material.SetFloat("_FlashAmount", flashAmount);
	}

	public void DestroySelf()
	{
		Object.Destroy(gameObject);
	}
}

