		attackPrefab = ChaosScytheObject.Prefab;
		destroyAttackObjectOnExit = false;
		updateSkillLevel = false;
		maxComboCount = 2;
		animStartTime = 0.2f;
		animExecTime = 0.3f;
		baseCancelThreshold = 0.55f;
		finalCancelThreshold = 0.75f;
		baseRunThreshold = 0.8f;
		finalRunThreshold = 0.9f;
		attackMoveSpeedMod = new NumVarStatMod(atkMoveModStr, 8f, 10, VarStatModType.OverrideWithMods);
		finalAttackMoveSpeedMod = new NumVarStatMod(atkMoveModStr, 16f, 10, VarStatModType.OverrideWithMods);
		chargeAtkMoveSpeed = 24f;
		autoHoldStat.BaseValue = true;
	}

	public override void SetEmpowered(bool gs, BoolVarStatMod ms)
	{
	}

	public override void OnEnter()
	{
		base.OnEnter();
		atkStarted = false;
		atkCompleted = false;
		queueFinalSpin = false;
	}

	public override void ExecuteAttack()
	{
		if (!atkStarted)
		{
			base.ExecuteAttack();
			if (useBaseMAS)
			{
				CameraController.ShakeCamera(0.12f);
				return;
			}
			if (!isCharged)
			{
				currentAttackObject.attack.ChangeAttackInfoLevel(2);
				PlayAttackObjAnim("SwingLarge");
				CameraController.ShakeCamera(0.18f);
				return;
			}
			spinAnimStr = ((!parent.forehandAnimPlayed) ? "Spin" : "SpinReverse");
			currentAttackObject.attack.ChangeAttackInfoLevel(3);
			currentAttackObject.negateScript.enabled = true;
			currentAttackObject.negateScript.skillCategory = parent.skillCategory;
			currentAttackObject.useAnimTime = false;
			atkStarted = true;
			atkStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, 0.15f, 2);
		}
		attackExecuted = atkCompleted;
	}

	public override void FixedUpdate()
	{
		if (!atkStarted || atkCompleted)
		{
			return;
		}
		if (!queueFinalSpin)
		{
			switch (ChaosStopwatch.CheckInterval(atkStopwatchID))
			{
			case StopwatchState.Ready:
				parent.movement.MoveToMoveVector();
				parent.anim.Play(spinAnimStr, -1, 0f);
				PlayAttackObjAnim("SpinFront");
				break;
			case StopwatchState.Done:
				queueFinalSpin = true;
				atkStopwatchID = ChaosStopwatch.Begin(0.15f);
				break;
			}
			return;
		}
		CancelToDash(enableButtonHeld: true);
		if (ChaosStopwatch.Check(atkStopwatchID))
		{
			atkCompleted = true;
			parent.movement.MoveToMoveVector();
			parent.anim.PlayDirectional(parent.LastHandAnimStr, -1, animExecTime);
			PlayAttackObjAnim("SwingLarge");
			if (currentAttackObject != null)
			{
				currentAttackObject.useLifeTime = true;
				currentAttackObject.lifeStopwatchID = ChaosStopwatch.Begin(0.5f);
				currentAttackObject.attack.ChangeAttackInfoLevel(4);
				(currentAttackObject as ChaosScytheObject).EmitRing();
			}
			if (repeatFinalHit)
			{
				cancelThreshold = baseCancelThreshold;
			}
		}
	}

	public override void OnExit()
	{
		base.OnExit();
		if (!attackExecuted && currentAttackObject != null)
		{
			currentAttackObject.useAnimTime = true;
		}
	}

	private void PlayAttackObjAnim(string givenStr)
	{
		if (currentAttackObject != null)
		{
			currentAttackObject.anim.Play(givenStr, -1, 0f);
		}
	}
}

