public class BaseJumpState : SkillState
{
	protected ThrownItem parentThrow;

	protected Vector2 startPosition;

	protected bool useCalcValues;

	protected float jumpRange = 5.5f;

	protected float jumpSpeed = 32f;

	protected float jumpTime = 0.5f;

	protected float jumpHeight = 1f;

	protected float jumpBalance = 0.5f;

	protected bool hasLanded;

	protected bool collidersEnabled;

	protected float landingDelay;

	protected ChaosQuickStopwatch landingStopwatch = new ChaosQuickStopwatch();

	public bool setInputVectorOnEnter = true;

	protected BoolVarStatMod airborneStatMod;

	public BaseJumpState(string skillID, FSM fsm, Player player)
		: base(skillID, fsm, player)
	{
		isMovementSkill = true;
		isJumpSkill = true;
		parentThrow = parent.throwScript;
		airborneStatMod = new BoolVarStatMod(skillID, newModValue: true, 3);
	}

	public override void OnEnter()
	{
		BaseOnEnter();
		base.ExecuteSkill();
		if (setInputVectorOnEnter)
		{
			inputVector = GetInputVector();
		}
		startPosition = parent.transform.position;
		parent.spriteRenderer.sortingLayerName = "UI";
		SetThrowValues();
		parentThrow.ThrowToTargetVector(Globals.GetSafeLinecastVector(startPosition, inputVector, jumpRange, ChaosCollisions.layerAllWallAndObst));
		landingStopwatch.SetDelay(landingDelay);
		SoundManager.PlayAudioWithDistance("StandardJump", startPosition);
		DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
		int particleCount = 50;
		float scale = 0.25f;
		Vector3? emitPosition = startPosition;
		poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
		hasLanded = false;
		collidersEnabled = false;
		ThrownItem thrownItem = parentThrow;
		thrownItem.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Remove(thrownItem.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
		ThrownItem thrownItem2 = parentThrow;
		thrownItem2.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Combine(thrownItem2.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
		ToggleObjects(status: false);
	}

	public override void Update()
	{
		if (hasLanded)
		{
			if (!collidersEnabled)
			{
				collidersEnabled = true;
				ToggleObjects(status: true);
			}
			if (!landingStopwatch.IsRunning)
			{
				ExitToSkillOrRunOrIdle();
			}
		}
	}

	public override void OnExit()
	{
		if (!hasLanded)
		{
			OnLanding();
		}
		base.OnExit();
		ToggleObjects(status: true);
		ThrownItem thrownItem = parentThrow;
		thrownItem.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Remove(thrownItem.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
	}

	public virtual void OnLanding()
	{
		hasLanded = true;
		landingStopwatch.IsRunning = true;
		parent.spriteRenderer.sortingLayerName = "Actor";
	}

	public virtual void ToggleObjects(bool status)
	{
		parent.airborneStat.Modify(airborneStatMod, !status);
		if (parent.hurtBoxObj != null && parent.hurtBoxObj.activeSelf != status)
		{
			parent.hurtBoxObj.SetActive(status);
		}
		if (parent.floorContact != null && parent.floorContact.activeSelf != status)
		{
			parent.floorContact.SetActive(status);
		}
		parent.TogglePreventFallCollider(status);
	}

	public virtual void SetThrowValues()
	{
		parentThrow.useCalculatedValues = useCalcValues;
		parentThrow.moveSpeed = jumpSpeed;
		parentThrow.baseFlightTime = jumpTime;
		parentThrow.throwHeight = jumpHeight;
		parentThrow.isFallingThreshold = jumpBalance;
	}
}

public class UseChaosDrop : BaseJumpState
{
	public new static string staticID = "UseChaosDrop";

	private float moveLerpValue;

	private ChaosQuickStopwatch moveStopwatch = new ChaosQuickStopwatch(0.125f);

	private bool moveCompleted;

	private int delayStopwatchID;

	private bool delayCompleted;

	private Vector2 dropPos;

	private Vector2 ultPos;

	private Vector2 ultVec;

	private bool ultDrop;

	private ChaosDropClone currentDC;

	public UseChaosDrop(FSM fsm, Player parentPlayer)
		: base(staticID, fsm, parentPlayer)
	{
		hasSignatureVariant = true;
		empoweredStat.SetInitialBaseValue(newBaseVal: true);
		isMeleeSkill = true;
		isProjectileSkill = true;
		SetAnimTimes(0f, 0.2f, 0.35f);
	}

	public override void SetEmpowered(bool gs, BoolVarStatMod gm)
	{
	}

	public override void OnEnter()
	{
		BaseOnEnter();
		base.ExecuteSkill();
		ToggleObjects(false);
		inputVector = GetInputVector(faceInputVector: true, useAimVector: true, ignoreZero: false);
		if (inputVector == Vector2.zero || (parent.inputDevice.IsMouseAim && parent.inputDevice.GetSqMouseDist < 5f))
		{
			inputVector = UnityEngine.Random.insideUnitCircle.normalized;
			jumpRange = 0f;
		}
		else
		{
			jumpRange = 5f;
		}
		startPosition = parent.transform.position;
		dropPos = Globals.GetSafeLinecastVector(startPosition, inputVector, jumpRange, ChaosCollisions.layerAllWallAndObst);
		CreateDropClone(startPosition, dropPos, inputVector, givenIsDrop: true, givenIsClone: false);
		if (isUltimate)
		{
			for (int i = 0; i < 4; i++)
			{
				ultVec = Globals.GetRotatedCircleVector(4, i, inputVector) * 1.75f;
				ultPos = dropPos + ultVec * 2f;
				ultDrop = !Globals.CheckCircle(ultPos, 0.25f, ChaosCollisions.layerAllWall);
				CreateDropClone(ultPos, dropPos + ultVec, -ultVec, ultDrop, givenIsClone: true);
			}
		}
		moveStopwatch.IsRunning = true;
		moveCompleted = false;
		delayCompleted = true;
		SoundManager.PlayWithDistAndSPR("ChaosBeamStart", startPosition);
		CameraController.ShakeCamera(0.3f);
	}

	public override void Update()
	{
		if (!moveCompleted)
		{
			return;
		}
		if (!delayCompleted)
		{
			if (ChaosStopwatch.Check(delayStopwatchID))
			{
				delayCompleted = true;
				parent.anim.PlayDirectional(parent.GSlamAnimStr, -1, animExecTime);
				ToggleVisuals(givenStatus: true);
			}
		}
		else
		{
			ExitToSkillOrRunOrIdle();
		}
	}

	public override void FixedUpdate()
	{
		if (!moveCompleted)
		{
			moveLerpValue = moveStopwatch.TimePercentage;
			parent.rigidbody2D.MovePosition(Vector2.Lerp(startPosition, dropPos, moveLerpValue));
			if (moveLerpValue >= 1f)
			{
				moveCompleted = true;
				parent.transform.position = dropPos;
				delayCompleted = false;
				delayStopwatchID = ChaosStopwatch.Begin(0.7f);
			}
		}
	}

	public override void ToggleObjects(bool givenStatus)
	{
		base.ToggleObjects(givenStatus);
		ToggleVisuals(givenStatus);
	}

	private void ToggleVisuals(bool givenStatus)
	{
		parent.spriteRenderer.gameObject.SetActive(givenStatus);
		parent.shadowSprite.gameObject.SetActive(givenStatus);
		parent.spriteTrail.Toggle(givenStatus && parent.overdriveReady);
	}

	private void CreateDropClone(Vector2 givenStart, Vector2 givenEnd, Vector2 givenVec, bool givenIsDrop, bool givenIsClone)
	{
		currentDC = ChaosInst<ChaosDropClone>(ChaosDropClone.Prefab, givenStart);
		currentDC.Initialize(parent, skillID, givenVec, FacingDirection.Down);
		currentDC.isUltimate = isUltimate;
		currentDC.atkVector = givenVec;
		currentDC.dropPos = givenEnd;
		currentDC.forceDrop = givenIsDrop;
		if (!givenIsClone)
		{
			currentDC.outfitIndex = parent.outfitColorIndex;
		}
	}
}

